import { ApplicationInsights } from '@microsoft/applicationinsights-web';
import type { ICustomProperties } from '@microsoft/applicationinsights-web';
import type { User } from '@/types/auth.types';
/**
 * Connection string is injected at **runtime** via @import-meta-env/unplugin
 * (see .env.dist / .env file loaded by the web server or Docker entrypoint).
 * It is NEVER baked into the compiled JS bundle at build time, so it does not
 * appear in your source code or your git history.
 *
 * The value is still visible inside the browser because the SDK must send
 * telemetry to the Azure ingestion endpoint directly. If you need to prevent
 * even that, route telemetry through a backend proxy and set
 * APPINSIGHTS_PROXY_URL to your proxy's endpoint.
 */
const connectionString = import.meta.env.APPINSIGHTS_CONNECTION_STRING as
  | string
  | undefined;
const cloudRole = import.meta.env.APPINSIGHTS_CLOUD_ROLE as string | undefined;
const isEnabled = import.meta.env.APPINSIGHTS_ENABLED === 'true';

/** Singleton AppInsights instance — use via the exported helpers below. */
let appInsights: ApplicationInsights | undefined;

/**
 * Initializes Azure Application Insights.
 * Call once at application startup (before app.mount).
 *
 * Controlled by the APPINSIGHTS_ENABLED env var:
 *   - 'true'  → tracking active
 *   - anything else (or missing) → tracking disabled, no network calls made
 */
export function initAppInsights(): void {
  if (!isEnabled) {
    return;
  }
  if (!connectionString) {
    console.warn(
      'App Insights not initialized: APPINSIGHTS_CONNECTION_STRING is required.',
    );
    return;
  }
  appInsights = new ApplicationInsights({
    config: {
      connectionString,

      // Optional backend proxy to route telemetry without exposing the
      // Ingestion endpoint to end-user network inspection tools.
      // ...(proxyUrl ? { endpointUrl: proxyUrl } : {}),

      // Automatically track page views when the router changes URL.
      enableAutoRouteTracking: true,

      // Track unhandled promise rejections as exceptions.
      enableUnhandledPromiseRejectionTracking: true,

      // Track clicks, keyboard, and other user interactions.
      enableCorsCorrelation: true,

      // Mask all user input by default for privacy.
      isBrowserLinkTrackingEnabled: true,

      // Disable the built-in session storage cookie to stay GDPR-friendly
      // When using your own consent mechanism.
      disableCookiesUsage: false,
    },
  });

  // Removed telemetry initializer for ai.cloud.role as per user request.

  if (cloudRole) {
    appInsights.addTelemetryInitializer((envelope) => {
      if (envelope.tags) {
        Object.assign(envelope.tags, { 'ai.cloud.role': cloudRole });
      }
    });
  }

  appInsights.loadAppInsights();
  appInsights.trackPageView(); // Track initial page view.
}

/**
 * Sets the authenticated user context so Azure can correlate all telemetry
 * from this session to the signed-in user.
 *
 * Call this after your auth flow resolves a User object.
 * Pass null / call clearAppInsightsUser() on logout.
 * @param user - The authenticated user (from auth.types.ts).
 */
export function setAppInsightsUser(user: User): void {
  if (!appInsights) return;

  const userId = user.profile.email || 'anonymous';

  appInsights.setAuthenticatedUserContext(
    userId,
    undefined, // AccountId — set if you need multi-tenant correlation
    true, // StoreInCookie — persists context across page loads
  );

  // Attach user properties to every future telemetry item.
  appInsights.addTelemetryInitializer((item) => {
    const customProperties = item.data ?? {};
    customProperties['user.email'] = user.profile.email;
    customProperties['user.name'] =
      `${user.profile.given_name} ${user.profile.family_name}`;
    if (user.profile.groups?.length) {
      customProperties['user.groups'] = user.profile.groups;
    }
    Object.assign(item, { data: customProperties });
  });
}

/**
 * Clears the authenticated user context (call on logout).
 */
export function clearAppInsightsUser(): void {
  appInsights?.clearAuthenticatedUserContext();
}

/**
 * Tracks a named page view (call from router afterEach for clean names in Azure portal).
 * @param name name
 * @param url url
 */
export function trackAppInsightsPageView(name: string, url?: string): void {
  appInsights?.trackPageView({ name, uri: url });
}

/**
 * Tracks a custom named event (e.g. button clicks, feature usage).
 * @param name name
 * @param properties properties
 */
export function trackAppInsightsEvent(
  name: string,
  properties?: ICustomProperties,
): void {
  appInsights?.trackEvent({ name }, properties);
}

/**
 * Tracks a caught exception manually.
 * @param error error
 * @param properties properties
 */
export function trackAppInsightsException(
  error: Error,
  properties?: ICustomProperties,
): void {
  appInsights?.trackException({ exception: error }, properties);
}

/**
 * @returns the singleton ApplicationInsights instance, or undefined if not initialized.
 * Use this to access advanced features not covered by the helper functions above.
 * Note: appInsights is only initialized if APPINSIGHTS_ENABLED is 'true' and a connection string is provided.
 * Always check for undefined before using the returned instance.
 */
export function getAppInsights(): ApplicationInsights | undefined {
  return appInsights;
}

