interface RedirectToDowntimeOptions {
  cause?: number | string;
  currentPath?: string;
  gapId?: string;
  resource?: string;
  team?: string;
  ticket?: string;
}

/**
 * Redirects the user to the downtime view while preserving Event Center context.
 * @param root0 The redirect options.
 * @param root0.cause The downtime cause to persist in session storage.
 * @param root0.currentPath The current application path used to infer the
 * source screen.
 * @param root0.gapId The live-status gap identifier stored as the previous
 * resource.
 * @param root0.resource The target resource identifier used in the downtime route.
 * @param root0.team The live-status team identifier preserved for the return
 * flow.
 * @param root0.ticket The downtime ticket identifier used in the destination
 * route.
 */
export function redirectToDowntimeView({
  cause,
  currentPath,
  gapId,
  resource,
  team,
  ticket,
}: RedirectToDowntimeOptions): void {
  if (!ticket || !resource) return;

  const path = currentPath ?? globalThis.location.pathname;
  const downtimeBaseUrl = new URL('/downtime-ui/', globalThis.location.origin).toString();
  const url = new URL(
    `${resource}/downtime-view/${ticket}`,
    downtimeBaseUrl,
  ).toString();

  if (cause !== undefined && String(cause) !== '6') {
    sessionStorage.setItem('cause', String(cause));
  }

  if (path.includes('/live-status')) {
    sessionStorage.setItem('previousScreen', 'live-status');

    if (gapId) {
      sessionStorage.setItem('previousResource', gapId);
    }

    if (team) {
      sessionStorage.setItem('previousTeam', team);
    }
  } else if (path.includes('/edashboard')) {
    sessionStorage.setItem('previousScreen', 'edashboard');
    sessionStorage.setItem('previousResource', resource);
  }

  globalThis.location.href = url;
}

/**
 * Removes leading zeros from a string containing numbers, handling both single numbers and semicolon-separated multiple numbers.
 * @param input - The input string containing number(s) to process
 * @returns The processed string with leading zeros removed, or '0' if the result would be empty
 */
export function removeLeadingZeros(input: string): string {
  if (!input) return ''; // Handle empty input

  // If there's a semicolon, treat it as multiple numbers
  if (input.includes(';')) {
    return input
      .split(';')
      .map((part) => part.replace(/^0+/, '') || '0')
      .join(';');
  }
  // Single number case
  return input.replace(/^0+/, '') || '0';
}

import { datadogRum } from '@datadog/browser-rum';
import type { RumEvent } from '@datadog/browser-rum';
import type { User } from '@/types/auth.types';

// NOTE: These are dummy values. The real applicationId and clientToken will be injected by the proxy layer at runtime.
const applicationId = 'applicationId';
const clientToken = 'clientToken';
const site = import.meta.env.DD_SITE || 'datadoghq.eu';
const service = import.meta.env.DD_SERVICE || 'epart-board-ui';
const env = import.meta.env.DD_ENV || 'development';
const proxyUrl =`${import.meta.env.EPART_BOARD_BACKEND_URL}/datadog-proxy`;
const isEnabled = import.meta.env.DD_ENABLED === 'true';

/**
 * Patterns used to scrub PII from URLs and error messages before
 * data leaves the browser.
 */
const SENSITIVE_PARAM_PATTERN =
  /([?&])(token|access_token|authorization|password|secret|apikey|api_key|session_id)=[^&]*/gi;

const EMAIL_PATTERN = /\b[a-zA-Z0-9._%+-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)+\b/g;

function sanitizeUrl(url: string): string {
  return url.replace(SENSITIVE_PARAM_PATTERN, '$1$2=[REDACTED]');
}
//this need to be replaced with String#replaceAll()
function sanitizeMessage(message?: string): string | undefined {
  if (!message) return message;
  return message
    .replace(SENSITIVE_PARAM_PATTERN, '$1$2=[REDACTED]')
    .replace(EMAIL_PATTERN, '[REDACTED_EMAIL]');
}

export function initDatadogRum(): void {
  if (!isEnabled) {
    console.info('Datadog RUM is disabled (DD_ENABLED !== "true").');
    return;
  }

  if (!applicationId || !clientToken) {
    console.warn(
      'Datadog RUM not initialized: DD_APPLICATION_ID and DD_CLIENT_TOKEN are required.',
    );
    return;
  }

  datadogRum.init({
    applicationId,
    clientToken,
    site,
    service,
    env,
    version: import.meta.env.npm_package_version ?? '0.0.0',

    // Session sampling — adjust as needed (100 = all sessions tracked)
    sessionSampleRate: 100,
    // Session Replay sampling — keep at 0 to avoid recording user screens
    // unless explicitly needed and privacy-reviewed
    sessionReplaySampleRate: 0,

    // Track user interactions (clicks, taps, scrolls)
    trackUserInteractions: true,
    // Track resources (XHR, fetch, etc.) — must be true for RUM–Traces
    // correlation: the SDK injects traceparent headers on tracked resources.
    trackResources: true,
    // Track long-running tasks
    trackLongTasks: true,

    // Allow Datadog to capture action names (button text, element content)
    // so we can track which buttons and elements users interact with.
    // PII is still scrubbed by the beforeSend callback below.
    enablePrivacyForActionName: false,

    // Default privacy level for Session Replay (if ever enabled):
    // 'mask' ensures all text is replaced with asterisks
    defaultPrivacyLevel: 'mask',

    // Proxy: route RUM data through your own server so end-user devices
    // never communicate directly with Datadog (recommended by the docs).
    // Leave DD_PROXY_URL empty to send directly to Datadog.

     ...(proxyUrl ? { proxy: proxyUrl } : {}),

    // Allowed tracing origins — use the OTEL tracecontext propagator so the
    // `traceparent` / `tracestate` headers are injected on every matching request.
    // The backend reads these via its W3CTraceContextPropagator and exports the
    // correlated span to Datadog, enabling end-to-end RUM–APM linking.
    allowedTracingUrls: [
      { match: /https:\/\/mesx-.*\.app\.corp/, propagatorTypes: ['tracecontext'] },
      { match: /http:\/\/localhost/, propagatorTypes: ['tracecontext'] },
    ],

    // beforeSend: scrub sensitive data from every event before it leaves
    // the browser. This is the primary client-side security control.
    beforeSend: (event: RumEvent) => {
      // Sanitize view URLs
      if (event.view?.url) {
        event.view.url = sanitizeUrl(event.view.url);
      }

      // Sanitize resource URLs (API calls, assets)
      if (event.type === 'resource' && event.resource?.url) {
        event.resource.url = sanitizeUrl(event.resource.url);
      }

      // Sanitize error messages and stack traces
      if (event.type === 'error') {
        if (event.error?.message) {
          event.error.message = sanitizeMessage(event.error.message)!;
        }
        if (event.error?.stack) {
          event.error.stack = sanitizeMessage(event.error.stack);
        }
      }

      // Sanitize action target URLs
      if (event.type === 'action' && event.action?.target?.name) {
        event.action.target.name = sanitizeMessage(event.action.target.name)!;
      }

      // Return true to keep the event, false to drop it
      return true;
    },
  });
}

/**
 * Set the authenticated user context on the RUM session.
 * Only store non-sensitive identifiers — never passwords or tokens.
 * Ref: https://docs.datadoghq.com/data_security/real_user_monitoring/#user-identity-tracking
 */
export function setDatadogUser(user: User): void {
  if (!applicationId || !clientToken) return;

  datadogRum.setUser({
    id: user.profile.email,
    name: `${user.profile.given_name} ${user.profile.family_name}`,
    email: user.profile.email,
  });
}

/**
 * Clear user context (e.g. on logout).
 */
export function clearDatadogUser(): void {
  datadogRum.clearUser();
}

/**
 * Send a custom action to Datadog RUM for tracking specific user interactions.
 * Use this for programmatic events that are not automatically captured by click tracking.
 * @param name  A short, descriptive action name (no PII).
 * @param context  Optional key-value context to attach to the action.
 */
export function trackCustomAction(
  name: string,
  context?: Record<string, string | number | boolean>,
): void {
  datadogRum.addAction(name, context);
}

