/**
 * Normalizes a stored locale value to one of the supported route locale codes.
 * @param raw Raw locale value from session storage, local storage, or cached attributes.
 * @returns A supported locale code when recognized; otherwise undefined.
 */
function normalizePersistedLocale(
  raw?: string | null,
): SupportedLocale | undefined {
  return resolveSupportedLocale(raw);
}

/**
 * Returns the selected or stored locale, falling back to 'en'.
 * @returns The locale code used for locale-aware redirects and startup i18n.
 */
export function getPersistedLocale(): string {
  const sessionSelected = normalizePersistedLocale(
    sessionStorage.getItem('userSelectedLocalization'),
  );
  if (sessionSelected) return sessionSelected;

  const stored = normalizePersistedLocale(
    localStorage.getItem('userStoredLocalization'),
  );
  if (stored) return stored;

  try {
    const rawUserAttributes = localStorage.getItem('userAttributes');
    if (rawUserAttributes) {
      const parsed = JSON.parse(rawUserAttributes) as {
        locale?: string;
        userAttributes?: { locale?: string };
      };
      const attributeLocale = normalizePersistedLocale(
        parsed.userAttributes?.locale ?? parsed.locale,
      );
      if (attributeLocale) return attributeLocale;
    }
  } catch {
    // Ignore malformed cached user attributes and fall back to default locale.
  }

  const instance = getI18nInstance();
  const activeLocale = normalizePersistedLocale(
    (instance?.global.locale as string | undefined) ?? undefined,
  );
  return activeLocale ?? 'en';
}

router.beforeEach(async (to, _from, next) => {
  const pathSegments = to.path.split('/').filter(Boolean);
  const pathLanguage = pathSegments[1];

  if (pathLanguage) {
    const resolvedPathLanguage = resolveSupportedLocale(pathLanguage);
    if (resolvedPathLanguage && resolvedPathLanguage !== pathLanguage) {
      pathSegments[1] = resolvedPathLanguage;
      return next({
        path: `/${pathSegments.join('/')}`,
        query: to.query,
        hash: to.hash,
        replace: true,
      });
    }
  }

  // Apply locale from /epb-ui/:language if valid
  const languageParameter = to.params.language as string | undefined;
  const resolvedLanguage = resolveSupportedLocale(languageParameter);
  if (resolvedLanguage) {
    localStorage.setItem('userStoredLocalization', resolvedLanguage);
    const instance = getI18nInstance();
    if (instance && instance.global.locale !== resolvedLanguage) {
      (instance.global as { locale: string }).locale = resolvedLanguage;
    }
  }
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }
  const userAuth = useProfileStore();
  if (to.meta.requiresAuth) {
    // Pass the route object directly for proper meta access
    const appName = userAuth.getAppName(to);
    try {
      await userAuth.authenticateUser(appName);
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes(appName);
        const preferredLocale = getPersistedLocale();
        const currentRouteLocale = resolveSupportedLocale(
          (to.params.language as string | undefined) ?? undefined,
        );

        if (preferredLocale !== currentRouteLocale && pathSegments[1]) {
          pathSegments[1] = preferredLocale;
          return next({
            path: `/${pathSegments.join('/')}`,
            query: to.query,
            hash: to.hash,
            replace: true,
          });
        }
        await userAuth.authorizeUser(appName);
        setDatadogUser(user);
        setAppInsightsUser(user);
      } else {
        console.error('[router] User not found after authenticateUser');
        return next(`/${appBasePath}/unauthorized`);
      }
      return next();
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      console.error('[router] auth error', error);
      return next(`/${appBasePath}/unauthorized`);
    }
  }
  return next(); // Explicit return for non-authenticated routes
});
// Track named page views so Azure portal shows route names instead of raw URLs.
router.afterEach((to) => {
  const name =
    (to.meta.title as string | undefined) ??
    (to.name as string | undefined) ??
    to.path;
  trackAppInsightsPageView(name, to.fullPath);
});
export { router };

