import { createI18n, I18n } from 'vue-i18n';
// Import { useLocaleStore } from '../modules/picking-screen/store/local-store.ts';
import ar from './locales/ar.json';
import cz from './locales/cz.json';
import en from './locales/en.json';
import es from './locales/es-ES.json';
import esMX from './locales/es-MX.json';
import fr from './locales/fr.json';
import pl from './locales/pl.json';
import ptBR from './locales/pt-BR.json';
import pt from './locales/pt-PT.json';
import sk from './locales/sk.json';
import zh from './locales/zh-CN.json';
import zhHK from './locales/zh-HK.json';

/**
 * Setup the i18n instance with the selected locale and available messages.
 * @returns A promise that resolves to the i18n instance.
 */
export const supportedLocales = [
  'ar',
  'cz',
  'en',
  'es-es',
  'es-mx',
  'fr',
  'pl',
  'pt-pt',
  'pt-br',
  'sk',
  'zh-cn',
  'zh-hk',
] as const;
export type SupportedLocale = (typeof supportedLocales)[number];

const messages = Object.fromEntries([
  ['ar', ar],
  ['cz', cz],
  ['en', en],
  ['es-es', es],
  ['es-mx', esMX],
  ['fr', fr],
  ['pl', pl],
  ['pt-br', ptBR],
  ['pt-pt', pt],
  ['sk', sk],
  ['zh-cn', zh],
  ['zh-hk', zhHK],
]) as unknown as Record<SupportedLocale, Record<string, string>>;

let i18nInstance: I18n | undefined;

/**
 * Maps incoming locale values to the repo's canonical locale codes.
 * @param locale Locale value from storage, auth attributes, or route params.
 * @returns The canonical supported locale when recognized.
 */
export function resolveSupportedLocale(
  locale?: string | null,
): SupportedLocale | undefined {
  if (!locale) return undefined;

  const normalizedLocale = locale.trim();
  const loweredLocale = normalizedLocale.toLowerCase();

  if (supportedLocales.includes(loweredLocale as SupportedLocale)) {
    return loweredLocale as SupportedLocale;
  }

  if (loweredLocale === 'es') return 'es-es';
  if (loweredLocale === 'esmx') return 'es-mx';
  if (loweredLocale === 'pt') return 'pt-pt';
  if (loweredLocale === 'ptbr') return 'pt-br';
  if (loweredLocale === 'zh') return 'zh-cn';
  if (loweredLocale === 'zhhk') return 'zh-hk';

  return undefined;
}

/**
 * Initialize and return the i18n instance.
 * @param initialLocale Optional locale seed (must be in supportedLocales) otherwise defaults to 'en'.
 * @returns The created i18n instance.
 */
export async function setupI18n(initialLocale?: string): Promise<I18n> {
  const locale = resolveSupportedLocale(initialLocale) ?? 'en';
  i18nInstance = createI18n({
    locale,
    fallbackLocale: 'en',
    messages,
  });
  return i18nInstance;
}

/**
 * Access the already created i18n instance (undefined until setupI18n is called).
 * @returns The existing i18n instance or undefined if not initialized.
 */
export function getI18nInstance(): I18n | undefined {
  return i18nInstance;
}

