import { storeToRefs } from 'pinia';
import { inject, type ComputedRef, type Ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { redirectToDowntimeView } from '@/common/helpers/redirect-to-downtime';
import { useEventCenterStore } from '@/modules/EventCenter/stores/event-center.store';
import type {
  EventItem,
  EventCategory,
  TimeGroup,
  ViewType,
} from '@/modules/EventCenter/types/event-center.types';
import { useHierarchyStore } from '@/shared-stores/hierarchy-store';
import type { Notify } from '@/types/notify';

interface EmitFunction {
  (event: 'close'): void;
  (event: 'event-click', payload: EventItem): void;
  (event: 'event-update', payload: EventItem, comment: string): void;
}

interface UseEventCenterResult {
  activeTab: Ref<EventCategory>;
  activeView: Ref<ViewType>;
  charsRemaining: ComputedRef<number>;
  comment: Ref<string>;
  error: Ref<string | undefined>;
  filteredGroups: ComputedRef<Array<TimeGroup>>;
  goBack: () => void;
  groups: Ref<Array<TimeGroup>>;
  handleEventClick: (event: EventItem) => void;
  handleUpdate: () => Promise<void>;
  isLoading: Ref<boolean>;
  isSubmitting: Ref<boolean>;
  loadGroups: () => Promise<void>;
  maxChars: number;
  restoreEventId: Ref<string | undefined>;
  selectedEvent: Ref<EventItem | undefined>;
}

/**
 * Provides composable logic for Event Center.
 * @param emit - The emit function for event communication.
 * @returns Event center handlers.
 */
export function useEventCenter(emit: EmitFunction): UseEventCenterResult {
  const store = useEventCenterStore();
  const hierarchyStore = useHierarchyStore();
  const { t } = useI18n();
  const notify = inject<Notify>('notify', {
    error: () => {},
    success: () => {},
    warning: () => {},
  });
  const {
    activeTab,
    activeView,
    charsRemaining,
    comment,
    error,
    filteredGroups,
    groups,
    isLoading,
    isSubmitting,
    restoreEventId,
    selectedEvent,
  } = storeToRefs(store);

  /**
   * Handles event click.
   * @param event - The event item.
   */
  function handleEventClick(event: EventItem): void {
    emit('event-click', event);
    if (event.category === 'downtime' && event.ticket) {
      redirectToDowntimeView({
        cause: event.downtimeCauseCode,
        currentPath: globalThis.location.pathname,
        gapId: hierarchyStore.gapId,
        resource: hierarchyStore.resource,
        team: hierarchyStore.team,
        ticket: event.ticket,
      });
      return;
    }

    if (event.category === 'slowdown') {
      store.selectEvent(event);
    }
  }

  /**
   * Handles update action.
   */
  async function handleUpdate(): Promise<void> {
    if (!selectedEvent.value) return;

    const eventToUpdate = selectedEvent.value;
    const updatedComment = comment.value;
    const didUpdate = await store.submitUpdate();

    if (didUpdate) {
      notify.success({
        message: t('EVENT_CENTER_COMMENT_UPDATE_SUCCESS'),
        title: 'Success',
      });
      emit('event-update', eventToUpdate, updatedComment);
      return;
    }

    notify.error({
      message: t('EVENT_CENTER_COMMENT_UPDATE_FAILED'),
      title: t('ERROR'),
    });
  }

  return {
    activeTab,
    activeView,
    charsRemaining,
    comment,
    error,
    filteredGroups,
    goBack: store.goBack,
    groups,
    handleEventClick,
    handleUpdate,
    isLoading,
    isSubmitting,
    loadGroups: store.loadGroups,
    maxChars: store.maxChars,
    restoreEventId,
    selectedEvent,
  };
}

import { useProfileStore } from '@/Auth/store/user-auth-store';
import type { EventCenterHistoryHourApiDto } from '@/modules/EventCenter/types/event-center-history.types';
import type { UpdateEventCenterSdCommentPayload } from '@/modules/EventCenter/types/update-event-center-sd-comment.types';
import { normalizeInclusiveHourEndDateTime } from '@/modules/EventCenter/utils/event-center-history.mapper';
import { useDashboardStore } from '@/modules/epart-board/stores/dashboard';
import { useHierarchyStore } from '@/shared-stores/hierarchy-store';

const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;
const contentTypeHeader = 'content-type';

/**
 * Fetches the Event Center history for the current dashboard context.
 * @returns The hourly Event Center history items returned by the backend.
 */
export async function fetchEventCenterHistory(): Promise<
  Array<EventCenterHistoryHourApiDto>
> {
  if (!edashboardBackendBaseUrl) {
    throw new Error('Missing EPART_BOARD_BACKEND_URL for Event Center history');
  }

  const hierarchyStore = useHierarchyStore();
  const dashboardStore = useDashboardStore();
  const profileStore = useProfileStore();

  const { plant } = hierarchyStore;
  const { resource: resourceId } = hierarchyStore;
  const shiftStartDate =
    dashboardStore.startDatetime ??
    dashboardStore.shiftInfo?.currentShift?.startDatetime;
  const shiftEndDate =
    dashboardStore.endDatetime ??
    dashboardStore.shiftInfo?.currentShift?.endDatetime;
  const timezone = profileStore.userAttributes?.timezone;

  if (!plant) {
    throw new Error('Missing Event Center query context: plant');
  }

  if (!resourceId) {
    throw new Error('Missing Event Center query context: resourceId');
  }

  if (!shiftStartDate) {
    throw new Error('Missing Event Center query context: shiftStartDate');
  }

  if (!shiftEndDate) {
    throw new Error('Missing Event Center query context: shiftEndDate');
  }

  if (!timezone) {
    throw new Error('Missing Event Center query context: timezone');
  }

  const query = new URLSearchParams({
    plant,
    resourceId,
    shiftEndDate,
    shiftStartDate,
    timezone,
  });
  const headers: Record<string, string> = {
    [contentTypeHeader]: 'application/json',
  };

  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  const response = await fetch(
    `${edashboardBackendBaseUrl}/epart-board/event-center/history?${query.toString()}`,
    {
      method: 'GET',
      headers,
      credentials: 'include',
    },
  );

  if (!response.ok) {
    throw new Error(`Event Center history request failed (${response.status})`);
  }

  return (await response.json()) as Array<EventCenterHistoryHourApiDto>;
}

/**
 * Sends an updated slowdown comment to the Event Center backend.
 * @param payload The slowdown comment payload to persist.
 * @returns A promise that resolves once the comment update is accepted.
 */
export async function updateEventComment(
  payload: UpdateEventCenterSdCommentPayload,
): Promise<void> {
  if (!edashboardBackendBaseUrl) {
    throw new Error(
      'Missing EPART_BOARD_BACKEND_URL for Event Center comment update',
    );
  }

  const headers: Record<string, string> = {
    [contentTypeHeader]: 'application/json',
  };

  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  const normalizedPayload: UpdateEventCenterSdCommentPayload = {
    ...payload,
    endDateTime:
      normalizeInclusiveHourEndDateTime(payload.endDateTime) ??
      payload.endDateTime,
  };

  const response = await fetch(
    `${edashboardBackendBaseUrl}/epart-board/event-center/sd-comments`,
    {
      method: 'POST',
      headers,
      credentials: 'include',
      body: JSON.stringify(normalizedPayload),
    },
  );

  if (!response.ok) {
    throw new Error(`Event Center comment update failed (${response.status})`);
  }
}

