  const resource = String(hierarchyStore.resource ?? '').trim();
  const shiftStartDate = String(
    dashboardStore.startDatetime ??
      dashboardStore.shiftInfo?.currentShift?.startDatetime ??
      '',
  ).trim();
  const shiftEndDate = String(
    dashboardStore.endDatetime ??
      dashboardStore.shiftInfo?.currentShift?.endDatetime ??
      '',
  ).trim();
  const timezone = String(profileStore.userAttributes?.timezone ?? '').trim();

  return [plant, resource, shiftStartDate, shiftEndDate, timezone].join('|');
}

/**
 * Resolves the persisted comment text for a slowdown event.
 * @param event - The selected Event Center item.
 * @returns The current saved comment text.
 */
function getEventComment(event: EventItem): string {
  if (typeof event.description === 'string' && event.description.trim()) {
    return event.description;
  }

  if (event.descriptionParts.length === 0) {
    return '';
  }

  return event.descriptionParts
    .map((part) => part.text)
    .join('')
    .trim();
}

/**
 * Normalizes hour-like keys to `HH:mm` when possible.
 * @param value The raw hour key.
 * @returns The normalized hour key.
 */
function normalizeHourKey(value: string | undefined): string {
  const trimmed = (value ?? '').trim();
  const match = /\d{2}:\d{2}/.exec(trimmed);
  return match ? match[0] : trimmed;
}

/**
 * Converts text into event description parts.
 * @param text Event description text.
 * @returns Event description parts.
 */
function toDescriptionParts(text: string): Array<{ text: string }> {
  return text ? [{ text }] : [];
}

/**
 * Formats a Date into `HH:mm`.
 * @param value Date to format.
 * @returns Formatted time.
 */
function toHourMinute(value: Date): string {
  const hours = String(value.getHours()).padStart(2, '0');
  const minutes = String(value.getMinutes()).padStart(2, '0');
  return `${hours}:${minutes}`;
}

/**
 * Resolves slowdown comment text for one group.
 * @param group Target group.
 * @returns Slowdown comment text when present.
 */
function getGroupSlowdownComment(group: TimeGroup): string | undefined {
  const slowdownEvent = group.events.find(
    (eventItem) => eventItem.category === 'slowdown',
  );

  if (!slowdownEvent) {
    return undefined;
  }

  if (
    typeof slowdownEvent.description === 'string' &&
    slowdownEvent.description.trim().length > 0
  ) {
    return slowdownEvent.description.trim();
  }

  return undefined;
}

/**
 * Builds a synthetic slowdown event for immediate UI feedback.
 * @param group Target group.
 * @param description Slowdown comment text.
 * @returns A synthetic slowdown event.
 */
function createSyntheticSlowdownEvent(
  group: TimeGroup,
  description: string,
): EventItem {
  return {
    badgeColor: '#FFA726',
    badgeTextColor: '#111111',
    category: 'slowdown',
    description,
    descriptionParts: toDescriptionParts(description),
    endDateTime: group.endDateTime,
    id: `optimistic-slowdown:${group.startDateTime ?? group.time}`,
    startDateTime: group.startDateTime,
    time: group.time,
    type: 'Slowdown',
  };
}

/**
 * Applies a slowdown comment to a specific group, creating a synthetic event if needed.
 * @param group Target group.
 * @param description Slowdown comment text.
 * @returns Updated group.
 */
function applySlowdownCommentToGroup(
  group: TimeGroup,
  description: string,
): TimeGroup {
  const text = description.trim();
  const previousSlowdownComment = getGroupSlowdownComment(group)?.trim() ?? '';
  const previousGroupCommentText = group.comment?.text?.trim() ?? '';
  const shouldMirrorGroupComment =
    previousGroupCommentText.length === 0 ||
    previousGroupCommentText === previousSlowdownComment;

  if (!text) {
    return {
      ...group,
      events: group.events.filter(
        (eventItem) => eventItem.category !== 'slowdown',
      ),
      comment: shouldMirrorGroupComment ? undefined : group.comment,
    };
  }

  const hasSlowdown = group.events.some(
    (eventItem) => eventItem.category === 'slowdown',
  );

  if (!hasSlowdown) {
    const nextGroup: TimeGroup = {
      ...group,
      events: [...group.events, createSyntheticSlowdownEvent(group, text)],
    };

    if (!shouldMirrorGroupComment) {
      return nextGroup;
    }

    return {
      ...nextGroup,
      comment: {
        text,
        lastEditedTime: group.comment?.lastEditedTime,
      },
    };
  }

  const nextGroup: TimeGroup = {
    ...group,
    events: group.events.map((eventItem) => {
      if (eventItem.category !== 'slowdown') {
        return eventItem;
      }

      return {
        ...eventItem,
        description: text,
        descriptionParts: toDescriptionParts(text),
      };
    }),
  };

  if (!shouldMirrorGroupComment) {
    return nextGroup;
  }

  return {
    ...nextGroup,
    comment: {
      text,
      lastEditedTime: group.comment?.lastEditedTime,
    },
  };
}

/**
 * Applies an optimistic hour-level comment to a group.
 * @param group Target group.
 * @param nextComment Next comment payload.
 * @returns Updated group.
 */
function applyGroupCommentToGroup(
  group: TimeGroup,
  nextComment: TimeGroupComment,
): TimeGroup {
  const text = nextComment.text.trim();
  const previousGroupCommentText = group.comment?.text?.trim() ?? '';

  const nextEvents = group.events.map((eventItem) => {
    if (eventItem.category !== 'slowdown') {
      return eventItem;
    }

    const currentDescription = eventItem.description?.trim() ?? '';
    const shouldMirrorGroupComment =
      currentDescription.length === 0 ||
      currentDescription === previousGroupCommentText;

    if (!shouldMirrorGroupComment) {
      return eventItem;
    }

    return {
      ...eventItem,
      description: text || undefined,
      descriptionParts: text ? toDescriptionParts(text) : [],
    };
  });

  if (!text) {
    return {
      ...group,
      events: nextEvents,
      comment: undefined,
    };
  }

  return {
    ...group,
    events: nextEvents,
    comment: {
      text,
      lastEditedTime: nextComment.lastEditedTime,
    },
  };
}

export const useEventCenterStore = defineStore('eventCenter', () => {
  const groups = ref<Array<TimeGroup>>([]);
  const activeView = ref<ViewType>('list');
  const activeTab = ref<EventCategory>('all');
  const optimisticSlowdownCommentsByHour = ref<Record<string, string>>({});
  const optimisticGroupCommentsByHour = ref<Record<string, TimeGroupComment>>(
    {},
  );

  const selectedEvent = ref<EventItem | undefined>(undefined);
  const comment = ref<string>('');
  const isLoading = ref<boolean>(false);
  const isSubmitting = ref<boolean>(false);
  const error = ref<string | undefined>(undefined);
  const restoreEventId = ref<string | undefined>(undefined);
  const optimisticStateContextKey = ref<string>('');
  const loadGroupsRequestId = ref<number>(0);

  const maxChars = 255;

  const filteredGroups = computed<Array<TimeGroup>>(() => {
    if (activeTab.value === 'all') {
      return groups.value.map((group) => ({
        ...group,
        events: group.events.filter(
          (eventItem) => eventItem.category !== 'comment',
        ),
      }));
    }

    if (activeTab.value === 'comment') {
      return groups.value.map((group) => ({
        ...group,
        events: group.events.filter(
          (eventItem) => eventItem.category !== 'comment',
        ),
      }));
    }
    if (activeTab.value === 'notification') {
      return groups.value
        .map((group) => ({
          ...group,
          events: group.events.filter((eventItem) =>
            isNotificationEvent(eventItem),
          ),
        }))
        .filter((group) => group.events.length > 0);
    }

    return groups.value.map((group) => {
      const filteredEvents = group.events.filter(
        (eventItem) => eventItem.category === activeTab.value,
      );
      return {
        ...group,
        events: filteredEvents,
      };
    });
  });

  const charsRemaining = computed<number>(
    () => maxChars - comment.value.length,
  );

  /**
   *
   */
  function resetUiState(): void {
    activeTab.value = 'all';
    activeView.value = 'list';
    comment.value = '';
    error.value = undefined;
    selectedEvent.value = undefined;
    restoreEventId.value = undefined;
  }

  /**
   * Loads the Event Center groups for the active dashboard context.
   * @returns A promise that resolves when the groups have been loaded or reset after an error.
   */
  async function loadGroups(): Promise<void> {
    const requestId = loadGroupsRequestId.value + 1;
    loadGroupsRequestId.value = requestId;
    const nextContextKey = resolveEventCenterContextKey();
    const hasContextChanged =
      optimisticStateContextKey.value.length > 0 &&
      optimisticStateContextKey.value !== nextContextKey;

    if (hasContextChanged) {
      optimisticSlowdownCommentsByHour.value = {};
      optimisticGroupCommentsByHour.value = {};
      selectedEvent.value = undefined;
      restoreEventId.value = undefined;
      comment.value = '';
    }

    optimisticStateContextKey.value = nextContextKey;
    isLoading.value = true;
    error.value = undefined;
    try {
      const payload = await fetchEventCenterHistory();
      if (requestId !== loadGroupsRequestId.value) {
        return;
      }

      const mappedGroups = mapEventCenterHistoryHours(payload);

      const nextOptimisticSlowdownCommentsByHour = {
        ...optimisticSlowdownCommentsByHour.value,
      };

      for (const [hourKey, optimisticText] of Object.entries(
        nextOptimisticSlowdownCommentsByHour,
      )) {
        const targetGroup = mappedGroups.find(
          (group) => normalizeHourKey(group.time) === hourKey,
        );

        if (targetGroup) {
          const backendText = getGroupSlowdownComment(targetGroup) ?? '';
          const normalizedOptimisticText = optimisticText.trim();

          if (backendText === normalizedOptimisticText) {
            delete nextOptimisticSlowdownCommentsByHour[hourKey];
          }
        }
      }

      optimisticSlowdownCommentsByHour.value =
        nextOptimisticSlowdownCommentsByHour;

      // Reconcile optimistic hour-level comments: clear entry when backend has caught up.
      const nextOptimisticGroupCommentsByHour = {
        ...optimisticGroupCommentsByHour.value,
      };

      for (const [hourKey, optimisticEntry] of Object.entries(
        nextOptimisticGroupCommentsByHour,
      )) {
        const targetGroup = mappedGroups.find(
          (group) => normalizeHourKey(group.time) === hourKey,
        );

        if (targetGroup) {
          const backendText = targetGroup.comment?.text?.trim() ?? '';
          const optimisticText = optimisticEntry.text.trim();

          if (backendText === optimisticText) {
            delete nextOptimisticGroupCommentsByHour[hourKey];
          }
        }
      }

      optimisticGroupCommentsByHour.value = nextOptimisticGroupCommentsByHour;

      groups.value = mappedGroups.map((group) => {
        const groupHourKey = normalizeHourKey(group.time);
        const optimisticComment =
          optimisticSlowdownCommentsByHour.value[groupHourKey];
        const optimisticGroupComment =
          optimisticGroupCommentsByHour.value[groupHourKey];

        let nextGroup = group;

        if (optimisticComment !== undefined) {
          nextGroup = applySlowdownCommentToGroup(nextGroup, optimisticComment);
        }

        if (optimisticGroupComment !== undefined) {
          nextGroup = applyGroupCommentToGroup(
            nextGroup,
            optimisticGroupComment,
          );
        }

        return nextGroup;
      });
    } catch {
      if (requestId !== loadGroupsRequestId.value) {
        return;
      }

      error.value = 'Failed to load events.';
      groups.value = [];
    } finally {
      if (requestId === loadGroupsRequestId.value) {
        isLoading.value = false;
      }
    }
  }

  /**
   * Opens the comment view for the selected event.
   * @param event The event selected from the Event Center list.
   */
  function selectEvent(event: EventItem): void {
    selectedEvent.value = event;
    restoreEventId.value = undefined;
    comment.value = getEventComment(event);
    error.value = undefined;
    activeView.value = 'comment';
  }

  /**
   *
   */
  function goBack(): void {
    activeView.value = 'list';
    selectedEvent.value = undefined;
    comment.value = '';
    error.value = undefined;
  }

  /**
   * Applies a slowdown comment optimistically for a given hour in Event Center groups.
   * @param hour The group hour key (`HH:mm`).
   * @param text The slowdown comment text.
   */
  function applySlowdownCommentByHour(hour: string, text: string): void {
    const normalizedText = text.trim();
    const normalizedHour = normalizeHourKey(hour);

    optimisticSlowdownCommentsByHour.value = {
      ...optimisticSlowdownCommentsByHour.value,
      [normalizedHour]: normalizedText,
    };

    groups.value = groups.value.map((group) => {
      if (normalizeHourKey(group.time) !== normalizedHour) {
        return group;
      }
      return applySlowdownCommentToGroup(group, normalizedText);
    });

    if (
      selectedEvent.value?.category === 'slowdown' &&
      normalizeHourKey(selectedEvent.value.time) === normalizedHour
    ) {
      const matchedGroup = groups.value.find(
        (group) => normalizeHourKey(group.time) === normalizedHour,
      );
      const matchedSlowdownEvent = matchedGroup?.events.find(
        (eventItem) =>
          eventItem.category === 'slowdown' &&
          eventItem.startDateTime === selectedEvent.value?.startDateTime &&
          eventItem.endDateTime === selectedEvent.value?.endDateTime,
      );

      selectedEvent.value = matchedSlowdownEvent ?? {
        ...selectedEvent.value,
        description: normalizedText,
        descriptionParts: toDescriptionParts(normalizedText),
      };

      comment.value = normalizedText;
    }
  }

  /**
   *
   * @returns `true` when the comment update was persisted successfully.
   */
  async function submitUpdate(): Promise<boolean> {
    if (isSubmitting.value) return false;
    if (!selectedEvent.value) return false;

    const eventToUpdate = selectedEvent.value;
    const normalizedComment = comment.value.trim();
    const originalComment = getEventComment(eventToUpdate);

    if (normalizedComment === originalComment) return false;

    const hierarchyStore = useHierarchyStore();
    error.value = undefined;

    if (eventToUpdate.category !== 'slowdown') {
      error.value = 'Failed to update comment.';
      return false;
    }

    if (!eventToUpdate.startDateTime) {
      error.value = 'Failed to update comment.';
      return false;
    }

    if (!eventToUpdate.endDateTime) {
      error.value = 'Failed to update comment.';
      return false;
    }

    if (!hierarchyStore.plant) {
      error.value = 'Failed to update comment.';
      return false;
    }

    if (!hierarchyStore.resource) {
      error.value = 'Failed to update comment.';
      return false;
    }

    const previousGroups = groups.value;
    const previousOptimisticSlowdownCommentsByHour = {
      ...optimisticSlowdownCommentsByHour.value,
    };
    const previousSelectedEvent = selectedEvent.value;

    try {
      isSubmitting.value = true;

      const normalizedHour = normalizeHourKey(eventToUpdate.time);
      let matchedEventId = eventToUpdate.id;

      applySlowdownCommentByHour(eventToUpdate.time, normalizedComment);

      const matchedGroup = groups.value.find(
        (group) => normalizeHourKey(group.time) === normalizedHour,
      );
      const matchedEvent = matchedGroup?.events.find(
        (eventItem) =>
          eventItem.category === 'slowdown' &&
          eventItem.startDateTime === eventToUpdate.startDateTime &&
          eventItem.endDateTime === eventToUpdate.endDateTime,
      );

      if (matchedEvent) {
        matchedEventId = matchedEvent.id;
      }

      await updateEventComment({
        comment: normalizedComment || undefined,
        endDateTime: eventToUpdate.endDateTime,
        plant: hierarchyStore.plant,
        resourceId: hierarchyStore.resource,
        startDateTime: eventToUpdate.startDateTime,
      });

      restoreEventId.value = matchedEventId;
    } catch {
      groups.value = previousGroups;
      optimisticSlowdownCommentsByHour.value =
        previousOptimisticSlowdownCommentsByHour;
      selectedEvent.value = previousSelectedEvent;
      error.value = 'Failed to update comment.';
      return false;
    } finally {
      isSubmitting.value = false;
    }

    goBack();
    return true;
  }

  /**
   * Applies an hour-level comment optimistically for a given hour in Event Center groups.
   * @param hour The group hour key (`HH:mm`).
   * @param nextComment The next optimistic comment payload.
   */
  function applyGroupCommentByHour(
    hour: string,
    nextComment: TimeGroupComment,
  ): void {
    const normalizedHour = normalizeHourKey(hour);

    // Keep empty text as a delete sentinel so subsequent refreshes preserve the
    // Optimistic removal until the backend catches up.
    optimisticGroupCommentsByHour.value = {
      ...optimisticGroupCommentsByHour.value,
      [normalizedHour]: {
        ...nextComment,
        text: nextComment.text.trim(),
      },
    };

    groups.value = groups.value.map((group) => {
      if (normalizeHourKey(group.time) !== normalizedHour) {
        return group;
      }

      const optimisticComment =
        optimisticGroupCommentsByHour.value[normalizedHour];
      if (!optimisticComment) {
        return group;
      }

      return applyGroupCommentToGroup(group, optimisticComment);
    });

    if (
      selectedEvent.value?.category === 'slowdown' &&
      normalizeHourKey(selectedEvent.value.time) === normalizedHour
    ) {
      const matchedGroup = groups.value.find(
        (group) => normalizeHourKey(group.time) === normalizedHour,
      );
      const matchedSlowdownEvent = matchedGroup?.events.find(
        (eventItem) =>
          eventItem.category === 'slowdown' &&
          eventItem.startDateTime === selectedEvent.value?.startDateTime &&
          eventItem.endDateTime === selectedEvent.value?.endDateTime,
      );

      if (matchedSlowdownEvent) {
        selectedEvent.value = matchedSlowdownEvent;
        comment.value = getEventComment(matchedSlowdownEvent);
      }
    }
  }

  /**
   * Persists an hour-level comment for a given group.
   * @param time The group hour label (`HH:mm`).
   * @param text The next comment text. Empty text removes the comment.
   * @returns `true` when the comment was persisted successfully.
   */
  async function saveGroupComment(
    time: string,
    text: string,
  ): Promise<boolean> {
    if (isSubmitting.value) return false;

    const hierarchyStore = useHierarchyStore();
    const group = groups.value.find((g) => g.time === time);

    if (!hierarchyStore.plant || !hierarchyStore.resource) {
      return false;
    }

    if (!group?.startDateTime || !group?.endDateTime) {
      return false;
    }

    const previousGroups = groups.value;
    const previousOptimisticGroupCommentsByHour = {
      ...optimisticGroupCommentsByHour.value,
    };

    try {
      isSubmitting.value = true;
      const now = new Date();
      const normalizedText = text.trim();
      const optimisticComment: TimeGroupComment = {
        text: normalizedText,
        lastEditedTime: toHourMinute(now),
      };

      applyGroupCommentByHour(time, optimisticComment);

      await updateEventComment({
        comment: normalizedText || undefined,
        endDateTime: group.endDateTime,
        plant: hierarchyStore.plant,
        resourceId: hierarchyStore.resource,
        startDateTime: group.startDateTime,
        writeDateTime: now.toISOString(),
      });
    } catch {
      groups.value = previousGroups;
      optimisticGroupCommentsByHour.value =
        previousOptimisticGroupCommentsByHour;
      return false;
    } finally {
      isSubmitting.value = false;
    }

    return true;
  }

  return {
    activeTab,
    activeView,
    applyGroupCommentByHour,
    applySlowdownCommentByHour,
    charsRemaining,
    comment,
    error,
    filteredGroups,
    goBack,
    groups,
    isLoading,
    isSubmitting,
    loadGroups,
    maxChars,
    resetUiState,
    restoreEventId,
    saveGroupComment,
    selectEvent,
    selectedEvent,
    submitUpdate,
  };
});

