/**
 * Parses a clock-like duration string into total seconds.
 * @param value Raw duration value.
 * @returns Total seconds when the value is parseable, otherwise undefined.
 */
function parseClockDurationToSeconds(value: unknown): number | undefined {
  if (typeof value !== 'string' || !value.trim()) {
    return undefined;
  }

  const match = /^(\d+):(\d{2}):(\d{2})$/.exec(value.trim());

  if (!match) {
    return undefined;
  }

  const [, hours, minutes, seconds] = match;

  return Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds);
}

/**
 * Formats a duration expressed in seconds back to `H:MM:SS`.
 * @param totalSeconds Duration in seconds.
 * @returns A clock-like duration string.
 */
function formatSecondsAsClockDuration(totalSeconds: number): string {
  const normalizedSeconds = Math.max(Math.trunc(totalSeconds), 0);
  const hours = Math.floor(normalizedSeconds / 3600);
  const minutes = Math.floor((normalizedSeconds % 3600) / 60);
  const seconds = normalizedSeconds % 60;

  return `${hours}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

/**
 * Normalizes inclusive hour end timestamps (`HH:59:59`) to the next hour start (`HH+1:00:00.000`).
 * @param endDateTime Raw end timestamp.
 * @returns Normalized timestamp when applicable.
 */
export function normalizeInclusiveHourEndDateTime(
  endDateTime: string | undefined,
): string | undefined {
  if (!endDateTime?.includes(':59:59')) {
    return endDateTime;
  }

  const timestamp = Date.parse(endDateTime);
  if (Number.isNaN(timestamp)) {
    return endDateTime;
  }

  const nextHour = new Date(timestamp + 1000);
  const day = String(nextHour.getDate()).padStart(2, '0');
  const hours = String(nextHour.getHours()).padStart(2, '0');
  const month = String(nextHour.getMonth() + 1).padStart(2, '0');
  const year = nextHour.getFullYear();

  return `${year}-${month}-${day}T${hours}:00:00.000`;
}

/**
 * Returns true when a value is a non-empty string.
 * @param value Raw value to validate.
 * @returns Whether the value is a non-empty string.
 */
function hasNonEmptyString(value: unknown): boolean {
  return typeof value === 'string' && value.trim().length > 0;
}

/**
 * Extracts normalized downtime cause metadata from one raw downtime row.
 * @param item Raw downtime row.
 * @returns Parsed cause information used by notification and rendering logic.
 */
function getDowntimeCauseMetadata(
  item: Record<string, unknown>,
): DowntimeCauseMetadata {
  const descriptionCauses = ['causeDesc', 'causeDesc1', 'causeDesc2'].flatMap(
    (key) => {
      const value = item[key];

      return typeof value === 'string' && value.trim() ? [value.trim()] : [];
    },
  );
  const codeCauses = ['cause1', 'cause2', 'cause'].flatMap((key) => {
    const value = item[key];

    return typeof value === 'string' && value.trim() ? [value.trim()] : [];
  });
  const causeList = item.causes;
  const listedCauses = Array.isArray(causeList)
    ? causeList.flatMap((value) =>
        typeof value === 'string' && value.trim() ? [value.trim()] : [],
      )
    : [];
  const hasSubCause =
    ['cause1', 'cause2', 'causeDesc1', 'causeDesc2'].some((key) =>
      hasNonEmptyString(item[key]),
    ) || listedCauses.length > 1;
  const downtimeCauseCode = Number(item.cause);

  return {
    causeCode: Number.isFinite(downtimeCauseCode)
      ? downtimeCauseCode
      : undefined,
    causeList: [
      ...new Set([
        ...(descriptionCauses.length > 0 ? descriptionCauses : codeCauses),
        ...listedCauses,
      ]),
    ],
    hasSubCause,
  };
}

/**
 * Builds a fallback description for configuration transitions when the backend does not send one.
 * @param fromAction The previous configuration action.
 * @param action The next configuration action.
 * @returns A localized transition description when both values are available.
 */
function getConfigurationDescription(
  fromAction: string | undefined,
  action: string,
): string | undefined {
  const normalizedFromAction = fromAction?.trim();

  if (!normalizedFromAction) {
    return undefined;
  }

  const i18nGlobal = getI18nInstance()?.global as
    | { t: (key: string, values?: Record<string, string>) => string }
    | undefined;

  return (
    i18nGlobal?.t('EVENT_CENTER_CONFIGURATION_CHANGE', {
      from: normalizedFromAction,
      to: action,
    }) ?? `From ${normalizedFromAction} to ${action}`
  );
}

/**
 * Returns true when the second timestamp starts immediately after the first one ends.
 * Some Event Center payloads close an hour at `:59:59.000` and start the next one at
 * the next exact second, while others reuse the same boundary timestamp.
 * @param previousEndDateTime The previous event end timestamp.
 * @param nextStartDateTime The next event start timestamp.
 * @returns `true` when both timestamps represent adjacent boundaries.
 */
function isAdjacentBoundary(
  previousEndDateTime: string | undefined,
  nextStartDateTime: string | undefined,
): boolean {
  if (!previousEndDateTime || !nextStartDateTime) {
    return false;
  }

  if (previousEndDateTime === nextStartDateTime) {
    return true;
  }

  const previousTimestamp = Date.parse(previousEndDateTime);
  const nextTimestamp = Date.parse(nextStartDateTime);

  if (Number.isNaN(previousTimestamp) || Number.isNaN(nextTimestamp)) {
    return false;
  }

  return previousTimestamp + 1000 === nextTimestamp;
}

/**
 * Maps raw configuration rows for one history hour.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped configuration entries.
 */
function mapConfigurationItems(
  hour: EventCenterHistoryHourApiDto,
): Array<MappedEventEntry> {
  const configurationItems = Array.isArray(hour.configuration)
    ? hour.configuration
    : [];
  const hasSingleConfigurationItem = configurationItems.length === 1;

  return configurationItems.flatMap((item) => {
    const startDateTime =
      typeof item.dateHourFrom === 'string' ? item.dateHourFrom : undefined;
    const endDateTime =
      typeof item.dateHourTo === 'string' ? item.dateHourTo : undefined;
    const action = typeof item.action === 'string' ? item.action : undefined;
    const time =
      startDateTime && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;

    if (!action || time === undefined) {
      return [];
    }

    const directDescription =
      typeof item.description === 'string' && item.description.trim()
        ? item.description.trim()
        : undefined;
    const fromAction =
      typeof item.fromAction === 'string' && item.fromAction.trim()
        ? item.fromAction.trim()
        : undefined;
    const description =
      directDescription ?? getConfigurationDescription(fromAction, action);
    let duration: string | undefined;
    if (
      action !== 'N' &&
      typeof item.duration === 'string' &&
      item.duration.trim()
    ) {
      duration = item.duration.trim();
    }

    const event: EventItem = {
      badgeColor: '#DDE5FF',
      badgeTextColor: '#643B48',
      category: 'configuration',
      description,
      descriptionParts: description?.trim()
        ? [{ text: description.trim() }]
        : [],
      duration,
      endDateTime,
      id: `configuration:${startDateTime}:${action}`,
      isOngoing: item.isOngoing === true,
      startDateTime,
      time,
      type: action,
    };

    const mergeKey = fromAction;
    const stateKey = [action, fromAction ?? '', description ?? ''].join('|');
    const isConfigurationContinuationCandidate =
      hasSingleConfigurationItem &&
      startDateTime === hour.dateHourFrom &&
      time === `${hour.hour}:00`;

    return [
      {
        event,
        isConfigurationContinuationCandidate,
        mergeKey,
        stateKey,
      },
    ];
  });
}

/**
 * Maps raw downtime rows for one history hour.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped downtime entries.
 */
function mapDowntimeItems(
  hour: EventCenterHistoryHourApiDto,
): Array<MappedEventEntry> {
  const downtimeItems = Array.isArray(hour.downtime) ? hour.downtime : [];

  return downtimeItems.flatMap((item) => {
    let startDateTime = hour.dateHourFrom;
    if (typeof item.dateHourFrom === 'string') {
      startDateTime = item.dateHourFrom;
    }
    if (typeof item.startDate === 'string') {
      startDateTime = item.startDate;
    }

    let endDateTime = hour.dateHourTo;
    if (typeof item.dateHourTo === 'string') {
      endDateTime = item.dateHourTo;
    }
    if (typeof item.endDate === 'string') {
      endDateTime = item.endDate;
    }

    const time =
      startDateTime && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;
    const ticket =
      typeof item.ticket === 'string' && item.ticket.trim()
        ? item.ticket.trim()
        : undefined;
    const rawDowntimeRemark =
      typeof item.remark === 'string' ? item.remark.trim() : '';
    const downtimeRemark =
      rawDowntimeRemark && rawDowntimeRemark.toLowerCase() !== 'null'
        ? rawDowntimeRemark
        : undefined;

    if (ticket === undefined || time === undefined) {
      return [];
    }

    const downtimeCauseMetadata = getDowntimeCauseMetadata(item);
    const downtimeCauseList = downtimeCauseMetadata.causeList;

    const directDescription =
      typeof item.description === 'string' && item.description.trim()
        ? item.description.trim()
        : undefined;
    const isUnclassified =
      downtimeCauseList.length === 0 && directDescription === undefined;
    const type = isUnclassified ? 'UNCLASSIFIED' : (downtimeCauseList[0] ?? '');
    let description: string | undefined;
    if (Number(item.cause) === 6 || isUnclassified) {
      const i18nGlobal = getI18nInstance()?.global as
        | { t: (key: string) => string }
        | undefined;
      description =
        i18nGlobal?.t('EVENT_CENTER_UNCLASSIFIED_TICKET') ??
        'You have an unclassified ticket.';
    } else if (downtimeCauseList.length > 1) {
      description = downtimeCauseList.slice(1).join('; ');
    } else {
      description = directDescription;
    }

    const badgeStyle = getDowntimeBadgeStyleByCause(Number(item.cause));

    const duration =
      typeof item.duration === 'string' && item.duration.trim()
        ? item.duration.trim()
        : undefined;
    const isOngoingDowntime = !duration;
    const i18nGlobal = getI18nInstance()?.global as
      | { t: (key: string) => string }
      | undefined;
    const isOngoing =
      isOngoingDowntime ||
      item.isOngoing === true ||
      duration?.toLowerCase() === 'ongoing';

    const event: EventItem = {
      badgeColor: badgeStyle.badgeColor,
      badgeTextColor: badgeStyle.badgeTextColor,
      category: 'downtime',
      description,
      descriptionParts: description?.trim()
        ? [{ text: description.trim() }]
        : [],
      downtimeCauseCode: downtimeCauseMetadata.causeCode,
      downtimeHasSubCause: downtimeCauseMetadata.hasSubCause,
      downtimeRemark,
      duration: isOngoingDowntime
        ? (i18nGlobal?.t('EVENT_CENTER_ONGOING') ?? 'Ongoing')
        : duration,
      endDateTime,
      id: ticket,
      isOngoing,
      startDateTime,
      ticket,
      time,
      type,
    };

    return [{ event, mergeKey: `ticket:${ticket}` }];
  });
}

/**
 * Maps raw slowdown rows for one history hour.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped slowdown entries.
 */
function mapSlowdownItems(
  hour: EventCenterHistoryHourApiDto,
): Array<MappedEventEntry> {
  const comments = Array.isArray(hour.comments) ? hour.comments : [];
  let slowdownItems = comments.filter((item) => {
    const thresholdMinutes = resolveSlowdownThresholdMinutes(item, hour);

    return isSlowdownAboveThreshold(item.slowdown, thresholdMinutes);
  });

  if (slowdownItems.length === 0) {
    const thresholdMinutes = resolveSlowdownThresholdMinutes({}, hour);
    const hasHourSlowdown = isSlowdownAboveThreshold(
      hour.slowdown,
      thresholdMinutes,
    );

    if (hasHourSlowdown) {
      slowdownItems = [
        {
          dateHourFrom: hour.dateHourFrom,
          dateHourTo: hour.dateHourTo,
          description: hour.description,
          id: `slowdown:${hour.dateHourFrom ?? hour.hour ?? 'unknown'}`,
          slowdown: hour.slowdown,
          slowdownMax: thresholdMinutes,
          type: 'Slowdown',
        },
      ];
    }
  }

  return slowdownItems.flatMap((item) => {
    const startDateTime =
      typeof item.dateHourFrom === 'string'
        ? item.dateHourFrom
        : hour.dateHourFrom;
    let endDateTime =
      typeof item.dateHourTo === 'string' ? item.dateHourTo : hour.dateHourTo;

    if (endDateTime?.endsWith(':59:59.000')) {
      const timestamp = Date.parse(endDateTime);

      if (!Number.isNaN(timestamp)) {
        const nextSecond = new Date(timestamp + 1000);
        const day = String(nextSecond.getDate()).padStart(2, '0');
        const hours = String(nextSecond.getHours()).padStart(2, '0');
        const minutes = String(nextSecond.getMinutes()).padStart(2, '0');
        const month = String(nextSecond.getMonth() + 1).padStart(2, '0');
        const seconds = String(nextSecond.getSeconds()).padStart(2, '0');
        const year = nextSecond.getFullYear();

        endDateTime = `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.000`;
      }
    }

    const time =
      startDateTime && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;

    if (time === undefined) {
      return [];
    }

    let description: string | undefined;
    if (typeof item.comment === 'string' && item.comment.trim()) {
      description = item.comment.trim();
    } else if (
      typeof item.description === 'string' &&
      item.description.trim()
    ) {
      description = item.description.trim();
    }

    const slowdownValue = parseNonZeroSlowdownMinutes(item.slowdown);
    const thresholdMinutes = resolveSlowdownThresholdMinutes(item, hour);

    if (!isSlowdownAboveThreshold(item.slowdown, thresholdMinutes)) {
      return [];
    }

    const event: EventItem = {
      badgeColor: 'rgb(236 178 185 / 50%)',
      badgeTextColor: '#643B48',
      category: 'slowdown',
      description,
      descriptionParts: description?.trim()
        ? [{ text: description.trim() }]
        : [],
      duration:
        typeof item.duration === 'string' && item.duration.trim()
          ? item.duration.trim()
          : undefined,
      endDateTime,
      id: `slowdown:${startDateTime ?? hour.hour ?? 'unknown'}`,
      isOngoing: item.isOngoing === true,
      slowdownDuration:
        item.slowdown === undefined ? undefined : String(item.slowdown),
      slowdownMax: String(thresholdMinutes),
      slowdownValue,
      startDateTime,
      time,
      type: 'Slowdown',
    };

    return [{ event }];
  });
}

/**
 * Maps raw hour-level comments into comment events.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped comment entries.
 */
function mapCommentItems(
  hour: EventCenterHistoryHourApiDto,
): Array<MappedEventEntry> {
  const comments = Array.isArray(hour.comments) ? hour.comments : [];
  const seenCommentKeys = new Set<string>();

  return comments.flatMap((item, index) => {
    const startDateTime =
      typeof item.dateHourFrom === 'string'
        ? item.dateHourFrom
        : hour.dateHourFrom;
    const endDateTime = normalizeInclusiveHourEndDateTime(
      typeof item.dateHourTo === 'string' ? item.dateHourTo : hour.dateHourTo,
    );
    const time =
      startDateTime && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;

    if (time === undefined) {
      return [];
    }

    let description: string | undefined;
    if (typeof item.comment === 'string' && item.comment.trim()) {
      description = item.comment.trim();
    } else if (
      typeof item.description === 'string' &&
      item.description.trim()
    ) {
      description = item.description.trim();
    }

    if (!description) {
      return [];
    }

    const commentKind = item.slowdown === undefined ? 'hour' : 'slowdown';
    const dedupeKey = `${time}|${commentKind}|${description}`;

    if (seenCommentKeys.has(dedupeKey)) {
      return [];
    }

    seenCommentKeys.add(dedupeKey);

    const event: EventItem = {
      badgeColor: '#E6F2FF',
      badgeTextColor: '#3558E0',
      category: 'comment',
      description,
      descriptionParts: [{ text: description }],
      endDateTime,
      id: `comment:${startDateTime ?? hour.hour ?? 'unknown'}:${commentKind}:${index}`,
      startDateTime,
      time,
      type: '',
    };

    return [{ event }];
  });
}

/**
 * Coerces an unknown quantity field to a string representation.
 * @param value The raw quantity value from the backend.
 * @returns A trimmed numeric string, or undefined when the value is unusable.
 */
function parseScrapCount(value: unknown): string | undefined {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return String(value);
  }

  if (typeof value === 'string' && value.trim()) {
    return value.trim();
  }

  return undefined;
}

/**
 * Coerces an unknown field to a trimmed string.
 * @param value The raw value from the backend.
 * @returns A trimmed string, or undefined when empty / non-string.
 */
function parseScrapString(value: unknown): string | undefined {
  if (typeof value === 'string' && value.trim()) {
    return value.trim();
  }

  return undefined;
}

/**
 * Builds the rendered rework cause description and emphasized parts.
 * @param causeDesc The primary rework cause description.
 * @param subcauseDesc The secondary rework cause description.
 * @returns Both raw description suffix and description parts for card rendering.
 */
function resolveReworkCauseContent(
  causeDesc: string | undefined,
  subcauseDesc: string | undefined,
): {
  causeDescription: string | undefined;
  causeDescriptionParts: Array<{ bold?: boolean; text: string }>;
} {
  const causeDescriptionParts: Array<{ bold?: boolean; text: string }> = [];
  const parts = [causeDesc, subcauseDesc].filter(Boolean) as Array<string>;

  if (parts.length === 0) {
    return { causeDescription: undefined, causeDescriptionParts };
  }

  for (const part of parts) {
    causeDescriptionParts.push({ text: ', ' }, { bold: true, text: part });
  }

  return {
    causeDescription: `, ${parts.join(', ')}`,
    causeDescriptionParts,
  };
}

/**
 * Builds the rendered scrap cause description and emphasized parts.
 * @param causeDesc The primary scrap cause description.
 * @param subcauseDesc The secondary scrap cause description.
 * @returns Both raw description suffix and description parts for card rendering.
 */
function resolveScrapCauseContent(
  causeDesc: string | undefined,
  subcauseDesc: string | undefined,
): {
  causeDescription: string | undefined;
  causeDescriptionParts: Array<{ bold?: boolean; text: string }>;
} {
  let causeDescription: string | undefined;
  const causeDescriptionParts: Array<{ bold?: boolean; text: string }> = [];

  if (causeDesc && subcauseDesc) {
    causeDescription = `, ${causeDesc}, ${subcauseDesc}`;
    causeDescriptionParts.push(
      { text: ', ' },
      { bold: true, text: causeDesc },
      { text: ', ' },
      { bold: true, text: subcauseDesc },
    );
  } else if (subcauseDesc) {
    causeDescription = `, ${subcauseDesc}`;
    causeDescriptionParts.push(
      { text: ', ' },
      { bold: true, text: subcauseDesc },
    );
  } else if (causeDesc) {
    causeDescription = `, ${causeDesc}`;
    causeDescriptionParts.push({ text: ', ' }, { bold: true, text: causeDesc });
  }

  return {
    causeDescription,
    causeDescriptionParts,
  };
}

/**
 * Maps raw scrap rows for one history hour.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped scrap entries.
 */
function mapScrapItems(
  hour: EventCenterHistoryHourApiDto,
): Array<MappedEventEntry> {
  let scrapItems: Array<Record<string, unknown>> = [];
  if (Array.isArray(hour.scraps)) {
    scrapItems = hour.scraps;
  }

  const i18nGlobal = getI18nInstance()?.global as
    | { t: (key: string) => string }
    | undefined;
  const ofText = ` ${i18nGlobal?.t('EVENT_CENTER_OF') ?? 'of'} `;

  return scrapItems.flatMap((item) => {
    const scrapStartDateTime =
      typeof item.creationDate === 'string' && item.creationDate.trim()
        ? item.creationDate.trim()
        : undefined;
    const startDateTime = scrapStartDateTime ?? hour.dateHourFrom;
    const endDateTime = hour.dateHourTo;
    const time =
      typeof startDateTime === 'string' && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;

    if (time === undefined) {
      return [];
    }

    const rawQuantity = item.quantity;
    const count = parseScrapCount(rawQuantity);
    const material = parseScrapString(item.materialId);
    const causeDesc = parseScrapString(item.cause);
    const subcauseDesc = parseScrapString(item.subCause);

    const normalizedCauseLabel = i18nGlobal?.t('SCRAP') ?? 'SCRAP';

    const { causeDescription, causeDescriptionParts } =
      resolveScrapCauseContent(causeDesc, subcauseDesc);

    const scrapDescription = count;

    const descriptionSegments = [
      scrapDescription,
      material ? `${ofText}${material}` : undefined,
      causeDescription,
    ].filter((segment): segment is string => segment !== undefined);

    const description = descriptionSegments.join('');
    const descriptionParts = [
      count
        ? {
            bold: true,
            text: count,
          }
        : undefined,
      material
        ? {
            text: ofText,
          }
        : undefined,
      material
        ? {
            text: material,
          }
        : undefined,
      ...causeDescriptionParts,
    ].filter(
      (part): part is { text: string; bold?: boolean } => part !== undefined,
    );
    const eventId = [
      'scrap',
      startDateTime ?? hour.dateHourFrom ?? time,
      normalizedCauseLabel,
      material ?? '',
      count ?? '',
    ].join(':');

    const event: EventItem = {
      badgeColor: '#CC1919',
      badgeTextColor: '#FFFFFF',
      category: 'scraps',
      description,
      descriptionParts,
      endDateTime,
      id: eventId,
      startDateTime,
      time,
      type: normalizedCauseLabel,
    };

    return [{ event }];
  });
}

