/**
 * Maps raw production change rows for one history hour.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped production change entries.
 */
function mapChangeProductionItems(
  hour: EventCenterHistoryHourApiDto,
): Array<MappedEventEntry> {
  const changeItems = Array.isArray(hour.changeProd) ? hour.changeProd : [];

  const normalizedItems = changeItems.flatMap((item, index) => {
    const startDateTime =
      typeof item.startTime === 'string' && item.startTime.trim()
        ? item.startTime.trim()
        : hour.dateHourFrom;
    const time =
      typeof startDateTime === 'string' && startDateTime.length >= 16
        ? startDateTime.slice(11, 16)
        : undefined;

    if (time === undefined) {
      return [];
    }

    const label =
      typeof item.label === 'string' && item.label.trim()
        ? item.label.trim()
        : undefined;

    if (!label) {
      return [];
    }

    const durationInSeconds = parseClockDurationToSeconds(item.duration);

    return [
      {
        durationInSeconds,
        index,
        label,
        startDateTime,
        time,
      },
    ];
  });

  if (normalizedItems.length === 0) {
    return [];
  }

  const i18nGlobal = getI18nInstance()?.global as
    | { t: (key: string) => string }
    | undefined;
  const changeProductionType =
    i18nGlobal?.t('EVENT_CENTER_FILTER_PRODUCTION_CHANGE') ??
    'Production Change';

  return normalizedItems.map((item) => {
    const descriptionParts = item.label
      .split(',')
      .map((part) => part.trim())
      .filter(Boolean)
      .map((part) => ({ text: part }));

    const event: EventItem = {
      badgeColor: '#9DB2F9',
      badgeTextColor: '#FFFFFF',
      category: 'changeProd',
      description: item.label,
      descriptionParts,
      duration:
        item.durationInSeconds === undefined
          ? undefined
          : formatSecondsAsClockDuration(item.durationInSeconds),
      endDateTime: hour.dateHourTo,
      id: [
        'change-prod',
        item.startDateTime ?? hour.dateHourFrom ?? item.time,
        item.index,
      ].join(':'),
      startDateTime: item.startDateTime,
      time: item.time,
      type: changeProductionType,
    };

    return { event };
  });
}

/**
 * Normalizes one raw comment payload into the all-tab comment shape.
 * @param commentEntry The raw backend comment entry.
 * @returns The mapped group comment, when the payload contains text.
 */
function mapGroupCommentEntry(
  commentEntry: Record<string, unknown> | undefined,
): TimeGroupComment | undefined {
  if (!commentEntry) return undefined;

  let rawComment: string | undefined;
  if (typeof commentEntry.comment === 'string' && commentEntry.comment.trim()) {
    rawComment = commentEntry.comment;
  } else if (
    typeof commentEntry.description === 'string' &&
    commentEntry.description.trim()
  ) {
    rawComment = commentEntry.description;
  }

  if (!rawComment) return undefined;

  const text = rawComment.trim();
  const editTimeCandidates = [
    commentEntry.writeDateTime,
    commentEntry.lastEditedTime,
    commentEntry.updateDateTime,
    commentEntry.updatedAt,
  ];

  const lastEditedTime = editTimeCandidates
    .filter(
      (candidate): candidate is string =>
        typeof candidate === 'string' && candidate.trim().length > 0,
    )
    .map((candidate) => {
      const clockMatch = /(\d{2}:\d{2})/.exec(candidate.trim());

      return clockMatch?.[1];
    })
    .find((value) => value !== undefined);

  return { text, lastEditedTime };
}

/**
 * Chooses the most relevant comment entry, preferring latest explicit edit metadata.
 * @param comments Candidate comment entries.
 * @returns The best matching comment entry.
 */
function pickMostRecentCommentEntry(
  comments: Array<Record<string, unknown>>,
): Record<string, unknown> | undefined {
  if (comments.length === 0) {
    return undefined;
  }

  const rank = (entry: Record<string, unknown>): number => {
    let score = 0;

    if (
      typeof entry.writeDateTime === 'string' &&
      entry.writeDateTime.trim().length > 0
    ) {
      score += 2;
    }

    if (
      typeof entry.lastEditedTime === 'string' &&
      entry.lastEditedTime.trim().length > 0
    ) {
      score += 1;
    }

    if (
      typeof entry.updateDateTime === 'string' &&
      entry.updateDateTime.trim().length > 0
    ) {
      score += 1;
    }

    if (
      typeof entry.updatedAt === 'string' &&
      entry.updatedAt.trim().length > 0
    ) {
      score += 1;
    }

    return score;
  };

  const toTimestamp = (entry: Record<string, unknown>): number => {
    const candidates = [
      entry.writeDateTime,
      entry.updateDateTime,
      entry.updatedAt,
    ];

    const parsedTimestamp = candidates
      .filter(
        (candidate): candidate is string =>
          typeof candidate === 'string' && candidate.trim().length > 0,
      )
      .map((candidate) => Date.parse(candidate))
      .find((timestamp) => !Number.isNaN(timestamp));

    return parsedTimestamp ?? Number.NEGATIVE_INFINITY;
  };

  return [...comments].sort((left, right) => {
    const rankDiff = rank(right) - rank(left);

    if (rankDiff !== 0) {
      return rankDiff;
    }

    return toTimestamp(right) - toTimestamp(left);
  })[0];
}

/**
 * Extracts the hour-level comment from the API response.
 * Comments that have no `slowdown` field are treated as hour-level comments.
 * @param hour The raw hourly API response bucket.
 * @returns The hour comment if available.
 */
function mapHourComment(
  hour: EventCenterHistoryHourApiDto,
): TimeGroupComment | undefined {
  const comments = Array.isArray(hour.comments) ? hour.comments : [];
  const hourComments = comments.filter((item) => item.slowdown === undefined);

  // If the payload contains an explicit hour-comment row, trust it (including empty = deleted)
  // And do not rehydrate the card from slowdown comments.
  if (hourComments.length > 0) {
    return mapGroupCommentEntry(pickMostRecentCommentEntry(hourComments));
  }

  const slowdownComments = comments.filter(
    (item) =>
      item.slowdown !== undefined &&
      ((typeof item.comment === 'string' && item.comment.trim()) ||
        (typeof item.description === 'string' && item.description.trim())),
  );

  return mapGroupCommentEntry(pickMostRecentCommentEntry(slowdownComments));
}

/**
 * Maps one hourly API response bucket to an Event Center time group.
 * @param hour The raw hourly API response bucket.
 * @returns The mapped time group.
 */
function mapHourToGroup(
  hour: EventCenterHistoryHourApiDto,
): MappedTimeGroup | undefined {
  const time =
    hour.dateHourFrom && hour.dateHourFrom.length >= 16
      ? hour.dateHourFrom.slice(11, 16)
      : hour.hour;

  if (time === undefined) {
    return undefined;
  }

  const events = [
    ...mapDowntimeItems(hour),
    ...mapSlowdownItems(hour),
    ...mapChangeProductionItems(hour),
    ...mapConfigurationItems(hour),
    ...mapCommentItems(hour),
    ...mapScrapItems(hour),
    ...mapReworkItems(hour),
  ].sort((left, right) => left.event.time.localeCompare(right.event.time));

  const hourComment = mapHourComment(hour);

  return {
    comment: hourComment,
    events,
    groupEnd: hour.dateHourTo,
    groupStart: hour.dateHourFrom,
    time,
  };
}

/**
 * Merges matching configuration and downtime events across successive hour groups.
 * @param groups The mapped hour groups to merge.
 * @returns The merged time groups ready for display.
 */
function mergeSuccessiveEvents(
  groups: Array<MappedTimeGroup>,
): Array<TimeGroup> {
  const mergedGroups = groups.map((group) => ({
    ...group,
    events: [...group.events],
  }));
  const previousEventByCategoryAndKey = new Map<string, MergeState>();
  let previousConfigurationState: ConfigurationState | undefined;

  for (const [groupIndex, group] of mergedGroups.entries()) {
    const nextEvents: Array<MappedEventEntry> = [];

    for (const entry of group.events) {
      if (entry.event.category === 'configuration') {
        const configurationStateKey = entry.stateKey;
        const shouldSuppressConfigurationContinuation =
          entry.isConfigurationContinuationCandidate === true &&
          configurationStateKey !== undefined &&
          previousConfigurationState?.stateKey === configurationStateKey &&
          isAdjacentBoundary(
            previousConfigurationState.endDateTime,
            entry.event.startDateTime,
          );

        previousConfigurationState = {
          endDateTime: entry.event.endDateTime,
          stateKey:
            configurationStateKey ??
            [entry.event.type, entry.event.description ?? ''].join('|'),
        };

        if (!shouldSuppressConfigurationContinuation) {
          nextEvents.push(entry);
        }
      } else {
        let mergeMapKey: string | undefined;
        if (entry.event.category === 'downtime' && entry.mergeKey) {
          mergeMapKey = `${entry.event.category}:${entry.mergeKey}`;
        }

        if (mergeMapKey === undefined) {
          nextEvents.push(entry);
        } else {
          const previousEntry = previousEventByCategoryAndKey.get(mergeMapKey);
          const isSuccessive =
            groupIndex > 0 &&
            previousEntry?.groupEnd !== undefined &&
            previousEntry.groupEnd === group.groupStart;

          if (!isSuccessive || previousEntry === undefined) {
            nextEvents.push(entry);
            previousEventByCategoryAndKey.set(mergeMapKey, {
              event: entry.event,
              firstEndDateTime: entry.event.endDateTime,
              groupEnd: group.groupEnd,
            });
          } else {
            let mergedDuration: string | undefined;
            const startTimestamp = previousEntry.firstEndDateTime?.trim()
              ? Date.parse(previousEntry.firstEndDateTime)
              : Number.NaN;
            const endTimestamp = entry.event.endDateTime?.trim()
              ? Date.parse(entry.event.endDateTime)
              : Number.NaN;

            if (
              !Number.isNaN(startTimestamp) &&
              !Number.isNaN(endTimestamp) &&
              endTimestamp > startTimestamp
            ) {
              const totalMinutes = Math.round(
                (endTimestamp - startTimestamp) / 60_000,
              );

              if (totalMinutes < 60) {
                mergedDuration = `${totalMinutes} min`;
              } else {
                const hours = Math.floor(totalMinutes / 60);
                const minutes = totalMinutes % 60;

                mergedDuration =
                  minutes === 0 ? `${hours}h` : `${hours}h ${minutes} min`;
              }
            }

            const mergedEvent: EventItem = {
              ...previousEntry.event,
              downtimeRemark:
                entry.event.downtimeRemark ??
                previousEntry.event.downtimeRemark,
              endDateTime: entry.event.endDateTime,
              isOngoing:
                previousEntry.event.isOngoing === true
                  ? true
                  : entry.event.isOngoing,
            };

            if (mergedDuration !== undefined) {
              mergedEvent.duration = mergedDuration;
            }

            previousEventByCategoryAndKey.set(mergeMapKey, {
              ...previousEntry,
              event: mergedEvent,
              groupEnd: group.groupEnd,
            });
          }
        }
      }
    }

    group.events = nextEvents;
  }

  return mergedGroups.map((group) => ({
    comment: group.comment,
    endDateTime: group.groupEnd,
    events: group.events.map(({ event }) => event),
    startDateTime: group.groupStart,
    time: group.time,
  }));
}

/**
 * Maps the Event Center history API response to grouped UI data.
 * @param payload The raw hourly history payload from the backend.
 * @returns The grouped Event Center view model.
 */
export function mapEventCenterHistoryHours(
  payload: Array<EventCenterHistoryHourApiDto>,
): Array<TimeGroup> {
  const groups = payload.flatMap((hour) => {
    const group = mapHourToGroup(hour);

    if (group === undefined) {
      return [];
    }

    return [group];
  });

  return mergeSuccessiveEvents(groups);
}

import type { EventItem } from '@/modules/EventCenter/types/event-center.types';

const NOTIFICATION_DOWNTIME_CAUSES = new Set([1, 4, 5, 6]);

/**
 * Returns true for slowdown events that still have no justification.
 * @param eventItem Event candidate from history payload.
 * @returns Whether the slowdown event needs user action.
 */
function isUnjustifiedSlowdown(eventItem: EventItem): boolean {
  if (eventItem.category !== 'slowdown') {
    return false;
  }

  if (
    typeof eventItem.description === 'string' &&
    eventItem.description.trim().length > 0
  ) {
    return false;
  }

  return !eventItem.descriptionParts.some(
    (part) => part.text.trim().length > 0,
  );
}

/**
 * Returns true for downtime events that should be shown in Notifs.
 * @param eventItem Event candidate from history payload.
 * @returns Whether the downtime event requires user interaction.
 */
function isActionableDowntime(eventItem: EventItem): boolean {
  if (eventItem.category !== 'downtime') {
    return false;
  }

  const isUnclassified = eventItem.type.trim().toUpperCase() === 'UNCLASSIFIED';
  const normalizedRemark =
    typeof eventItem.downtimeRemark === 'string'
      ? eventItem.downtimeRemark.trim()
      : '';
  const hasRemark =
    normalizedRemark.length > 0 && normalizedRemark.toLowerCase() !== 'null';

  if (hasRemark) {
    return false;
  }

  if (isUnclassified) {
    return true;
  }

  return (
    eventItem.downtimeHasSubCause === false &&
    typeof eventItem.downtimeCauseCode === 'number' &&
    NOTIFICATION_DOWNTIME_CAUSES.has(eventItem.downtimeCauseCode)
  );
}

/**
 * Returns true when an Event Center event should be listed under Notifs.
 * @param eventItem Event candidate from history payload.
 * @returns Whether the event requires user interaction.
 */
export function isNotificationEvent(eventItem: EventItem): boolean {
  return isUnjustifiedSlowdown(eventItem) || isActionableDowntime(eventItem);
}

import type { EventCenterHistoryHourApiDto } from '@/modules/EventCenter/types/event-center-history.types';

/**
 * Parses slowdown values as direct minutes and returns non-zero values only.
 * Accepts number or numeric strings (e.g. `13`, `13.5`, `13,5`).
 * Does not transform clock formats like `HH:MM:SS`.
 * @param value The raw slowdown value.
 * @returns Non-zero slowdown in minutes, or undefined when zero/not numeric.
 */
export function parseNonZeroSlowdownMinutes(
  value: unknown,
): number | undefined {
  let numericValue = Number.NaN;

  if (typeof value === 'number') {
    numericValue = value;
  } else if (typeof value === 'string') {
    numericValue = Number.parseFloat(value.trim().replace(',', '.'));
  }

  if (!Number.isFinite(numericValue) || numericValue === 0) {
    return undefined;
  }

  return numericValue;
}

/**
 * Resolves slowdown threshold minutes from a raw payload object.
 * @param source The raw payload object that may contain a threshold field.
 * @returns The threshold in minutes when parsable.
 */
function parseSlowdownThresholdMinutes(
  source: Record<string, unknown> | undefined,
): number | undefined {
  if (!source) {
    return undefined;
  }

  const candidateKeys = [
    'slowdownMax',
    'slowdownThreshold',
    'threshold',
    'sdMax',
    'maxSlowdown',
  ] as const;

  for (const key of candidateKeys) {
    const parsedMinutes = parseNonZeroSlowdownMinutes(source[key]);

    if (parsedMinutes !== undefined) {
      return Math.abs(parsedMinutes);
    }
  }

  return undefined;
}

/**
 * Resolves slowdown threshold for one raw slowdown row.
 * @param item The raw slowdown row.
 * @param hour The parent hour payload.
 * @returns Threshold in minutes (defaults to 5 when absent).
 */
export function resolveSlowdownThresholdMinutes(
  item: Record<string, unknown>,
  hour: EventCenterHistoryHourApiDto,
): number {
  const hourLike = hour as unknown as Record<string, unknown>;

  return (
    parseSlowdownThresholdMinutes(item) ??
    parseSlowdownThresholdMinutes(hourLike) ??
    5
  );
}

/**
 * Determines whether slowdown exceeds its configured threshold.
 * @param slowdownValue Raw slowdown value.
 * @param thresholdMinutes Threshold in minutes.
 * @returns True when slowdown is greater than threshold.
 */
export function isSlowdownAboveThreshold(
  slowdownValue: unknown,
  thresholdMinutes: number,
): boolean {
  const parsedSlowdownMinutes = parseNonZeroSlowdownMinutes(slowdownValue);

  if (parsedSlowdownMinutes === undefined) {
    return false;
  }

  return Math.abs(parsedSlowdownMinutes) > Math.abs(thresholdMinutes);
}

