      <input
        v-model="searchText"
        type="text"
        class="gap-select-input"
        :placeholder="t('SEARCH_FOR_MLEAN_GAP_IN_LIST')"
        @focus="handleFocus"
        @blur="handleBlur"
        @keydown.arrow-down="selectNextOption"
        @keydown.arrow-up="selectPreviousOption"
        @keydown.enter="selectHighlightedOption"
        @keydown.escape="isOpen = false"
      />
      <svg class="dropdown-icon" :class="{ rotated: isOpen }" width="14" height="14" viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M10.5 8.75L7 5.25L3.5 8.75" stroke="#1E1E1E" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
    </div>
    <div v-if="isOpen" class="dropdown-list">
      <div
        v-for="(gap, index) in filteredGaps"
        :key="gap.id"
        class="dropdown-option"
        :class="{ highlighted: index === highlightedIndex, selected: gap.id === modelValue }"
        @click="selectOption(gap.id)"
        @mouseenter="highlightedIndex = index"
      >
        {{ gap.displayText }}
      </div>
      <div v-if="filteredGaps.length === 0" class="dropdown-option no-results">
        {{ t('NO_RESULTS_FOUND') }}
      </div>
    </div>
