<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import type { GapOption } from '@/types/gap-api.types'

interface Props {
  modelValue: string
  gaps: GapOption[]
}

const props = defineProps<Props>()
const { t } = useI18n()
const emit = defineEmits<{
  'update:modelValue': [value: string]
}>()

const searchText = ref('')
const isOpen = ref(false)
const highlightedIndex = ref(0)
const previousSelectedGap = ref(props.modelValue)
// Sync previousSelectedGap when modelValue changes externally
watch(() => props.modelValue, (newValue) => {
  previousSelectedGap.value = newValue
  const selectedGap = props.gaps.find(gap => gap.id === newValue)
  if (selectedGap && !isOpen.value) {
    searchText.value = selectedGap.displayText
  }
})

const filteredGaps = computed(() => {
  if (!searchText.value.trim()) {
    return props.gaps
  }
  const query = searchText.value.toLowerCase()
  return props.gaps.filter(gap =>
    gap.displayText.toLowerCase().includes(query) ||
    gap.name.toLowerCase().includes(query)
  )
})

const selectOption = (gapId: string) => {
  emit('update:modelValue', gapId)
  previousSelectedGap.value = gapId
  const selectedGap = props.gaps.find(gap => gap.id === gapId)
  if (selectedGap) {
    searchText.value = selectedGap.displayText
  }
  isOpen.value = false
  highlightedIndex.value = 0
}

const selectHighlightedOption = () => {
  if (filteredGaps.value.length > 0 && highlightedIndex.value < filteredGaps.value.length) {
    selectOption(filteredGaps.value[highlightedIndex.value].id)
  }
}

const selectNextOption = () => {
  if (highlightedIndex.value < filteredGaps.value.length - 1) {
    highlightedIndex.value++
  }
}

const selectPreviousOption = () => {
  if (highlightedIndex.value > 0) {
    highlightedIndex.value--
  }
}

const handleBlur = () => {
  setTimeout(() => {
    isOpen.value = false
    // Restore previous selection if no new selection was made
    const selectedGap = props.gaps.find(gap => gap.id === previousSelectedGap.value)
    if (selectedGap) {
      searchText.value = selectedGap.displayText
    }
  }, 200)
}

const handleFocus = () => {
  isOpen.value = true
  searchText.value = ''
  highlightedIndex.value = 0
}

</script>

