      task: Omit<Task, 'id' | 'createdAt' | 'status'>,
    ): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const newTask: Task = {
          ...task,
          id: `${task.type}_${Date.now()}`,
          createdAt: new Date().toISOString(),
          status: 'pending',
        };
        station.tasks.push(newTask);
      }
    },

    removeTask(stationId: string, taskId: string): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const index = station.tasks.findIndex((t) => t.id === taskId);
        if (index !== -1) {
          station.tasks.splice(index, 1);
        }
      }
    },

    updateTask(
      stationId: string,
      taskId: string,
      updates: Partial<Task>,
    ): void {
      const station = this.stations.find((s) => s.id === stationId);
      if (station) {
        const task = station.tasks.find((t) => t.id === taskId);
        if (task) {
          Object.assign(task, updates, { updatedAt: new Date().toISOString() });
        }
      }
    },

    filterTasks(criteria: TaskCriteria): Array<Task> {
      return this.stations.flatMap((station) =>
        station.tasks.filter((task) => {
          return Object.entries(criteria).every(([key, value]) => {
            if (Array.isArray(value)) {
              return value.includes(task[key as keyof Task] as string);
            }
            return (task[key as keyof Task] as string) === value;
          });
        }),
      );
    },
  },
});

import type { ResourceApiResponse, ResourceCardData, ResourceCardKpi } from '@/types/resource-card.types';
import { statusCodeToColor, statusTokenToCode } from './status-utils';
import { getCurrentTimeInTimezone } from '@/utils/helpers/get-current-time-in-timezone';

interface MapResourcesToCardsOptions {
  shiftStartDate?: string;
  shiftEndDate?: string;
  timezone?: string;
}

function computeShiftHours(shiftStartDate?: string, shiftEndDate?: string): number {
  if (!shiftStartDate || !shiftEndDate) {
    return 8;
  }

  const start = new Date(shiftStartDate).getTime();
  const end = new Date(shiftEndDate).getTime();
  const durationMs = end - start;

  if (!Number.isFinite(durationMs) || durationMs <= 0) {
    return 8;
  }

  return Math.max(1, Math.round(durationMs / (60 * 60 * 1000)));
}

function computeTimelineProgressPercent(
  shiftStartDate?: string,
  shiftEndDate?: string,
  timezone?: string,
): number {
  if (!shiftStartDate || !shiftEndDate) {
    return 100;
  }

  const start = new Date(shiftStartDate).getTime();
  const end = new Date(shiftEndDate).getTime();
  const durationMs = end - start;

  if (!Number.isFinite(durationMs) || durationMs <= 0) {
    return 100;
  }

  const now = getCurrentTimeInTimezone(timezone).getTime();

  const progress = ((now - start) / durationMs) * 100;
  return Math.max(0, Math.min(100, progress));
}

function buildSlotTimelineSegments(
  status: string,
  shiftHours: number,
  options?: MapResourcesToCardsOptions,
): string[] {
  if (!status || status.trim() === '') {
    return Array.from({ length: shiftHours * 12 }, () => statusCodeToColor(6));
  }

  const statusTokens = status.split(';');
  if (statusTokens.length === 0) {
    return Array.from({ length: shiftHours * 12 }, () => statusCodeToColor(6));
  }

  const shiftStartMs = options?.shiftStartDate
    ? new Date(options.shiftStartDate).getTime()
    : Number.NaN;
  const hasShiftStart = Number.isFinite(shiftStartMs);
  const nowMs = getCurrentTimeInTimezone(options?.timezone).getTime();
  const slotDurationMs = 5 * 60 * 1000;

  return statusTokens.map((slotToken, slotIndex) => {
    const trimmed = slotToken.trim();
    if (trimmed === '') {
      if (!hasShiftStart) {
        return 'transparent';
      }

      const slotStartMs = shiftStartMs + slotIndex * slotDurationMs;
      return slotStartMs < nowMs ? statusCodeToColor(0) : 'transparent';
    }
    return statusCodeToColor(statusTokenToCode(trimmed));
  });
}

function getHeaderTextColor(backgroundColor: string): string {
  const normalized = backgroundColor.replace('#', '');
  const safeHex = normalized.length === 3
    ? normalized
        .split('')
        .map((char) => `${char}${char}`)
        .join('')
    : normalized;

  if (safeHex.length !== 6) {
    return '#ffffff';
  }

  const red = Number.parseInt(safeHex.slice(0, 2), 16);
  const green = Number.parseInt(safeHex.slice(2, 4), 16);
  const blue = Number.parseInt(safeHex.slice(4, 6), 16);
  const luminance = (0.299 * red + 0.587 * green + 0.114 * blue) / 255;

  return luminance > 0.6 ? '#1e242d' : '#ffffff';
}

/**
 * Converts a ResourceApiResponse to ResourceCardData.
 * Formats shift totals as KPIs and status string as timeline segments.
 *
 * @param resource - API response for a single resource
 * @returns Formatted ResourceCardData ready for display
 */
export function mapResourceToCard(
  resource: ResourceApiResponse,
  options?: MapResourcesToCardsOptions,
): ResourceCardData {
  const shiftHours = computeShiftHours(options?.shiftStartDate, options?.shiftEndDate);

  const kpis: ResourceCardKpi[] = [
    {
      label: 'TARGET',
      value: Math.round(resource.shiftTotals.target),
    },
    {
      label: 'PRODUCED',
      value: resource.shiftTotals.production,
    },
    {
      label: 'DELTA',
      value: Math.round(resource.shiftTotals.delta),
      color: resource.shiftTotals.delta < 0 ? '#C10015' : '#21BA45',
      bgColor: resource.shiftTotals.delta < 0 ? '#C10015' : '#21BA45',
    },
    {
      label: 'SCRAP',
      value: resource.shiftTotals.scrap,
    },
  ];

  const timelineSegments = buildSlotTimelineSegments(
    resource.status,
    shiftHours,
    options,
  );
  const timelineProgressPercent = computeTimelineProgressPercent(
    options?.shiftStartDate,
    options?.shiftEndDate,
    options?.timezone,
  );
  const lastNonTransparent = [...timelineSegments].reverse().find((c) => c !== 'transparent');
  const lastTimelineColor = lastNonTransparent ?? statusCodeToColor(6);
  const headerTextColor = getHeaderTextColor(lastTimelineColor);

  return {
    id: resource.resourceId,
    name: resource.resourceName,
    kpis,
    borderColor: lastTimelineColor,
    headerBgColor: lastTimelineColor,
    headerTextColor,
    timelineSegments,
    timelineProgressPercent,
  };
}

/**
 * Converts an array of API responses to an array of ResourceCardData.
 *
 * @param resources - Array of API responses
 * @returns Array of formatted cards
 */
export function mapResourcesToCards(
  resources: ResourceApiResponse[],
  options?: MapResourcesToCardsOptions,
): ResourceCardData[] {
  return resources.map((resource) => mapResourceToCard(resource, options));
}

/**
 * Status code to color mapping.
 * Aligned with shift-tracking-table slot-segment colors.
 */
const STATUS_COLOR_MAP: Record<number, string> = {
  0: '#87cb6a', // prod
  1: '#ba8be3', // op
  2: '#5e5e5e', // ps
  3: '#3dcaf2', // co
  4: '#e97871', // ls
  5: '#e5d07a', // qu
  6: '#d3d3d3', // uc
};

/**
 * Converts a raw status token to a status code.
 * Supports numeric strings ("0".."6") and special token "NA".
 * "NA" follows shift-tracking rules and is treated as production.
 */
export function statusTokenToCode(statusToken: string): number {
  const normalized = statusToken.trim().toUpperCase();

  if (normalized === 'NA') {
    return 0;
  }

  const parsed = Number.parseInt(normalized, 10);
  return Number.isNaN(parsed) ? 6 : parsed;
}

/**
 * Converts a status code (0-6 or other) to its corresponding color.
 * @param statusCode - The numeric status code
 * @returns CSS color string
 */
export function statusCodeToColor(statusCode: number): string {
  return STATUS_COLOR_MAP[statusCode] ?? STATUS_COLOR_MAP[6]; // Default to uc (gray)
}

/**
 * Parses a semicolon-separated status string and converts to color array.
 * Example input: "6;6;6;0;0;1;1;6"
 * Returns array of CSS color strings, one per status code.
 *
 * @param statusString - Semicolon-separated status codes
 * @returns Array of CSS color strings
 */
export function parseStatusStringToColors(statusString: string): string[] {
  if (!statusString || statusString.trim() === '') {
    return [];
  }

  return statusString
    .split(';')
    .map(code => code.trim())
    .filter(code => code !== '')
    .map(code => statusCodeToColor(statusTokenToCode(code)));
}

/**
 * Determines the border color based on status distribution.
 * If production (status 0) is dominant, use green.
 * If quality/scrap issues (status 4-5) are present, use red/orange.
 * Otherwise use gray.
 *
 * @param statusColors - Array of CSS color strings from parseStatusStringToColors
 * @returns CSS color string for border
 */
export function determineBorderColor(statusColors: string[]): string {
  if (statusColors.length === 0) {
    return statusCodeToColor(6);
  }

  const prodCount = statusColors.filter(c => c === statusCodeToColor(0)).length;
  const issueCount = statusColors.filter(
    c => c === statusCodeToColor(4) || c === statusCodeToColor(5),
  ).length;
  const totalCount = statusColors.length;

  if (issueCount > 0) {
    return statusCodeToColor(4);
  }

  if (prodCount > totalCount * 0.7) {
    return '#21ba45'; // Production green
  }

  return statusCodeToColor(6);
}

import { BrowserAgent } from '@newrelic/browser-agent/loaders/browser-agent';

const isEnabled = import.meta.env.NEWRELIC_ENABLED === 'true';
const applicationID = import.meta.env.NEWRELIC_APPLICATION_ID as
  | string
  | undefined;
const licenseKey = import.meta.env.NEWRELIC_LICENSE_KEY as string | undefined;
const accountID = import.meta.env.NEWRELIC_ACCOUNT_ID as string | undefined;
const trustKey = import.meta.env.NEWRELIC_TRUST_KEY as string | undefined;
const agentID = import.meta.env.NEWRELIC_AGENT_ID as string | undefined;
const beaconHost = 'bam.eu01.nr-data.net';

let browserAgent: BrowserAgent | undefined;

/**
 * Initializes New Relic Browser agent.
 * Controlled by NEWRELIC_ENABLED env var:
 *  - 'true' => enabled
 *  - anything else => disabled
 */
export function initNewRelicBrowserAgent(): void {
  if (!isEnabled) {
    return;
  }

  if (!applicationID || !licenseKey || !accountID || !trustKey || !agentID) {
    console.warn(
      'New Relic Browser Agent not initialized: NEWRELIC_APPLICATION_ID, NEWRELIC_LICENSE_KEY, NEWRELIC_ACCOUNT_ID, NEWRELIC_TRUST_KEY, and NEWRELIC_AGENT_ID are required.',
    );
    return;
  }

  if (browserAgent) {
    return;
  }

  try {
    browserAgent = new BrowserAgent({
      info: {
        applicationID,
        beacon: beaconHost,
        errorBeacon: beaconHost,
        licenseKey,
        sa: 1,
      },
      loader_config: {
        accountID,
        agentID,
        applicationID,
        licenseKey,
        trustKey,
      },
      init: {
        ajax: {
          deny_list: [beaconHost],
        },
        browser_consent_mode: {
          enabled: false,
        },
        distributed_tracing: {
          enabled: true,
        },
        performance: {
          capture_detail: false,
          capture_marks: false,
          capture_measures: true,
        },
        privacy: {
          cookies_enabled: true,
        },
      },
    });
  } catch (error) {
    console.error(
      'New Relic Browser Agent failed to initialize. App will continue without New Relic telemetry.',
      error,
    );
  }
}

/**
 *@returns The initialized New Relic Browser Agent instance, or undefined if the agent is not enabled or failed to initialize.
 */
export function getNewRelicBrowserAgent(): BrowserAgent | undefined {
  return browserAgent;
}

