/**
 * Load and refresh the STOPPAGE KPI for the selected plant/resource shift window.
 * @param stoppageApiService Service used to retrieve the STOPPAGE value.
 * @param hierarchyStore Store containing the selected plant and resource.
 * @param dashboardStore Store containing the active shift window.
 * @returns Reactive STOPPAGE count in rounded minutes.
 */
export function useStoppageCount(
  stoppageApiService: StoppageCountService,
  hierarchyStore: HierarchyStore,
  dashboardStore: DashboardStore,
): {
  stoppageCount: Ref<number | undefined>;
  stoppageDisplayValue: Ref<string | undefined>;
} {
  const stoppageCount = ref<number | undefined>(undefined);
  const stoppageDisplayValue = ref<string | undefined>(undefined);
  let intervalId: ReturnType<typeof setInterval> | undefined;

  const fetchStoppageCount = async (): Promise<void> => {
    const { plant, resource } = hierarchyStore;
    const { startDatetime, endDatetime } = dashboardStore;

    if (!plant || !resource || !startDatetime || !endDatetime) {
      stoppageCount.value = undefined;
      stoppageDisplayValue.value = undefined;
      return;
    }

    try {
      const shiftEnd = new Date(endDatetime);
      const now = new Date();
      const effectiveEnd = now < shiftEnd ? now : shiftEnd;

      const response = await stoppageApiService.getStoppageCount({
        endDate: effectiveEnd.toISOString(),
        plant,
        resource,
        startDate: new Date(startDatetime).toISOString(),
      });

      stoppageCount.value = response?.count;
      if (response?.causeDescription && response.displayDuration) {
        stoppageDisplayValue.value = `${response.causeDescription}|${response.displayDuration}`;
      } else if (response?.count === undefined) {
        stoppageDisplayValue.value = undefined;
      } else {
        stoppageDisplayValue.value = `${response.count}min`;
      }
    } catch (error) {
      console.error('Failed to fetch stoppage count:', error);
      stoppageCount.value = undefined;
      stoppageDisplayValue.value = undefined;
    }
  };

  onMounted(async () => {
    if (hierarchyStore.resource) {
      await fetchStoppageCount();
    }
    intervalId = setInterval(async () => {
      await fetchStoppageCount();
    }, 60_000);
  });

  onUnmounted(() => {
    if (intervalId) {
      clearInterval(intervalId);
      intervalId = undefined;
    }
  });

  watch(
    () => [
      hierarchyStore.resource,
      dashboardStore.startDatetime,
      dashboardStore.endDatetime,
    ],
    async () => {
      await fetchStoppageCount();
    },
  );

  return {
    stoppageCount,
    stoppageDisplayValue,
  };
}

import { ref, computed, watch, inject } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRoute, useRouter } from 'vue-router';
