import type { Notify } from '@/types/notify';
import type { TreeNodeType } from '@/types/tree-select.types';
import type {
  TreeSelectorProperties,
  UseTreeSelectorReturn,
} from '@/types/tree-selector.types';
import { TreeSelector } from '@/utils/tree-selector';
import { checkResourceIdExists } from '@/utils/utils';

/**
 * Finds details for a specific resource in a hierarchical dataset.
 * @param data - The hierarchical tree data to search.
 * @param resourceId - The unique ID of the resource to locate.
 * @returns The matched resource details object containing managedBy information or undefined if not found.
 */
function findResourceDetails(
  data: Array<unknown>,
  resourceId: string,
): { managedBy?: string } | undefined {
  const found = (data as Array<{ id: string; managedBy?: string }>).find(
    (item) => item.id === resourceId,
  );
  return found ? { managedBy: found.managedBy } : undefined;
}

// ...existing code...

let treeSelector: TreeSelector;

/**
 * Composable for managing tree selector logic
 * @param properties - Tree selector properties
 * @returns Tree selector state and methods
 */
export function useTreeSelector(
  properties: TreeSelectorProperties,
): UseTreeSelectorReturn {
  const route = useRoute();
  const router = useRouter();
  const userStore = useUserStore();
  const { t } = useI18n();
  const notify = inject<Notify>('notify');

  // Reactive state
  const treeData = ref<Array<TreeNodeType>>([]);
  const rawData = ref<Array<unknown>>([]);
  const searchQuery = ref('');
  const expandedNodes = ref(new Set<number | string>());
  const expandedNodesBeforeSearch = ref<Set<number | string> | null>(null);
  const selectedNode = ref<TreeNodeType | undefined>(undefined);
  const isLoading = ref(false);
  const isSelectingFromRoute = ref(false);

  treeSelector = new TreeSelector(
    router,
    route,
    userStore,
    properties,
    selectedNode,
    isSelectingFromRoute,
  );

  // Helper functions
  const filterTreeNodes = (
    nodes: Array<TreeNodeType>,
    query: string,
  ): Array<TreeNodeType> => {
    if (!query.trim()) return nodes;

    const filtered: Array<TreeNodeType> = [];
    const lowerQuery = query.trim().toLowerCase();

    const matchesQuery = (node: TreeNodeType): boolean => {
      const label = (node.label || '').toString().toLowerCase();
      const value =
        node.value !== undefined && node.value !== null
          ? String(node.value).toLowerCase()
          : '';
      const resourceId = node.meta?.resourceId
        ? String(node.meta.resourceId).toLowerCase()
        : '';
      const uapId = node.meta?.uapId
        ? String(node.meta.uapId).toLowerCase()
        : '';
      const productionLineId = node.meta?.productionLineId
        ? String(node.meta.productionLineId).toLowerCase()
        : '';
      const workcenterId = node.meta?.workcenterId
        ? String(node.meta.workcenterId).toLowerCase()
        : '';
      const gapId = node.meta?.gapId ? String(node.meta.gapId).toLowerCase() : '';
      const gapDesc = node.meta?.gapDesc ? String(node.meta.gapDesc).toLowerCase() : '';

      return (
        label.includes(lowerQuery) ||
        value.includes(lowerQuery) ||
        resourceId.includes(lowerQuery) ||
        uapId.includes(lowerQuery) ||
        productionLineId.includes(lowerQuery) ||
        workcenterId.includes(lowerQuery) ||
        gapId.includes(lowerQuery) ||
        gapDesc.includes(lowerQuery)
      );
    };

    const searchInNode = (node: TreeNodeType): TreeNodeType | undefined => {
      const matches = matchesQuery(node);
      const filteredChildren: Array<TreeNodeType> = [];

      if (node.children && node.children.length > 0) {
        for (const child of node.children) {
          const searchResult = searchInNode(child);
          if (searchResult) {
            filteredChildren.push(searchResult);
          }
        }
      }

      if (matches) {
        return {
          ...node,
          children: node.children ?? [], // keep ALL children when parent node matches
          isSearchMatch: true,
        };
      }

      if (filteredChildren.length > 0) {
        return {
          ...node,
          children: filteredChildren,
          isSearchMatch: false,
        };
      }

      return undefined;
    };

    for (const node of nodes) {
      const result = searchInNode(node);
      if (result) filtered.push(result);
    }

    return filtered;
  };

  const findResourceNode = (
    nodes: Array<TreeNodeType>,
    parameterValue: string,
    parameterName = 'resourceId',
  ): TreeNodeType | undefined => {
    for (const node of nodes) {
      // Check current node first (regardless of whether it has children)
      if (
        parameterName === 'gapId' &&
        node.meta?.gapId &&
        String(node.meta.gapId) === parameterValue
      ) {
        return node;
      }
      if (
        parameterName === 'resourceId' &&
        node.value === parameterValue &&
        node.meta?.resourceId
      ) {
        return node;
      }

      // Then search in children if they exist
      if (node.children && node.children.length > 0) {
        const found = findResourceNode(
          node.children,
          parameterValue,
          parameterName,
        );
        if (found) return found;
      }
    }
    return undefined;
  };

  const showResourceNotFoundError = (parameterName: string): void => {
    if (parameterName === 'gapId') {
      notify?.error({
        message: t('GAP_NOT_FOUND_FOR_PLANT'),
        title: t('GAP_NOT_FOUND'),
      });
    } else {
      notify?.error({
        message: t('RESOURCE_NOT_FOUND_FOR_PLANT'),
        title: t('RESOURCE_NOT_FOUND'),
      });
    }
  };

  const showResourceNotAccessibleError = (parameterName: string): void => {
    if (parameterName === 'gapId') {
      notify?.error({
        message: t('GAP_NOT_ACCESSIBLE'),
        title: t('GAP_NOT_FOUND'),
      });
    } else {
      notify?.error({
        message: t('RESOURCE_NOT_ACCESSIBLE'),
        title: t('RESOURCE_NOT_FOUND'),
      });
    }
  };

  const selectNode = (node: TreeNodeType): void => {
    // Update user attributes for managed by
    try {
      const resourceDetails = findResourceDetails(
        rawData.value,
        node.value as string,
      );
      if (resourceDetails && resourceDetails.managedBy) {
        // Store managedBy in state if needed
      }
    } catch (detailsError) {
      console.error(
        '[useTreeSelector] Resource details lookup error:',
        detailsError,
      );
    }

    treeSelector.select(node);
  };

  const selectResourceNode = (resourceNode: TreeNodeType): void => {
    isSelectingFromRoute.value = true;
    try {
      selectedNode.value = resourceNode;
      selectNode(resourceNode);
    } catch (selectError) {
      console.error('[useTreeSelector] Node selection error:', selectError);
      throw selectError;
    } finally {
      isSelectingFromRoute.value = false;
    }
  };

  const handleRouteResourceSelection = async (
    parameterValue: string,
    parameterName: string,
  ): Promise<void> => {
    const resourceExists = checkResourceIdExists(
      treeData.value,
      parameterValue,
      parameterName,
    );

    if (!resourceExists) {
      console.warn(
        '[useTreeSelector] Resource not found in API data:',
        parameterValue,
      );
      showResourceNotFoundError(parameterName);
      await router.push(properties.basePath || '/epb-ui');
      return;
    }

    const resourceNode = findResourceNode(
      treeData.value,
      parameterValue,
      parameterName,
    );

    if (resourceNode) {
      selectResourceNode(resourceNode);
    } else {
      console.warn(
        '[useTreeSelector] Resource in API but not in tree:',
        parameterValue,
      );
      showResourceNotAccessibleError(parameterName);
      await router.push(properties.basePath || '/epb-ui');
    }
  };

  const handleAssignedResourceSelection = async (): Promise<void> => {
    const hasResourceAttribute = userStore.userAttributes?.some(
      (attribute) => attribute.userAttributeName === 'resource',
    );

    if (!hasResourceAttribute) {
      return;
    }

    const assignedResource = userStore.userAttributes.find(
      (attribute) => attribute.userAttributeName === 'resource',
    )?.value;

    if (typeof assignedResource !== 'string') {
      return;
    }

    try {
      const resourceExists = checkResourceIdExists(
        treeData.value,
        assignedResource,
      );
      if (!resourceExists) {
        return;
      }

      treeData.value = HierarchyService.filterTreeByResource(
        treeData.value,
        assignedResource,
      );

      const resourceNode = findResourceNode(treeData.value, assignedResource);
      if (resourceNode) {
        selectedNode.value = resourceNode;
        selectNode(resourceNode);
      }
    } catch (error) {
      console.error(
        '[useTreeSelector] Assigned resource selection failed:',
        error,
      );
    }
  };

  const handleInitialResourceSelection = async (): Promise<void> => {
    const parameterName =
      (route.meta?.paramName as string) ||
      properties.routeParamName ||
      'resourceId';
    const parameterValue = route.params[parameterName] as string;

    if (parameterValue) {
      try {
        await handleRouteResourceSelection(parameterValue, parameterName);
      } catch (error) {
        console.error('[useTreeSelector] Resource selection error:', error);
        notify?.error({
          message: t('RESOURCE_SELECTION_ERROR'),
          title: t('ERROR'),
        });
        await router.push(properties.basePath || '/epb-ui');
      }
    } else {
      await handleAssignedResourceSelection();
    }
  };

  // Main functions
  const loadData = async (): Promise<void> => {
    if (!properties.apiFunction) {
      return;
    }

    try {
      isLoading.value = true;

      const response = await properties.apiFunction();

      if (Array.isArray(response)) {
        rawData.value = response;

        try {
          treeData.value = properties.transformFunction
            ? properties.transformFunction(response)
            : HierarchyService.transformApiToTree(response);
        } catch (transformError) {
          console.error(
            '[useTreeSelector] Tree transformation error:',
            transformError,
          );
          treeData.value = [];
          throw transformError;
        }
      } else {
        console.warn(
          '[useTreeSelector] API response is not an array:',
          typeof response,
        );
        rawData.value = [];
        treeData.value = [];
      }

      // Only attempt resource selection when we actually have data.
      // If data is empty (e.g. plant not yet resolved), skip to avoid
      // incorrectly redirecting away and wiping the gapId from the URL.
      if (rawData.value.length > 0) {
        await handleInitialResourceSelection();
      }
    } catch (error) {
      console.error('[useTreeSelector] Data loading error:', error);
    } finally {
      isLoading.value = false;
    }
  };

  const toggleNode = (nodeId: number | string): void => {
    if (expandedNodes.value.has(nodeId)) {
      expandedNodes.value.delete(nodeId);
    } else {
      expandedNodes.value.add(nodeId);
    }
  };

  const isNodeExpanded = (nodeId: number | string): boolean => {
    return expandedNodes.value.has(nodeId);
  };

  const expandAllNodes = (): void => {
    const expandNode = (nodes: Array<TreeNodeType>): void => {
      for (const node of nodes) {
        if (node.id) {
          expandedNodes.value.add(node.id);
        }
        if (node.children && node.children.length > 0) {
          expandNode(node.children);
        }
      }
    };
    expandNode(treeData.value);
  };

  const clearSearch = (): void => {
    searchQuery.value = '';
  };

  // Computed properties
  const filteredTreeData = computed(() => {
    return filterTreeNodes(treeData.value, searchQuery.value);
  });

  const displayText = computed(() => {
    // If a node is selected, format the selected text based on route context.
    if (selectedNode.value) {
      const label =
        selectedNode.value.label || String(selectedNode.value.value || '');

      const isLiveStatusRoute =
        (route.meta as { appName?: string })?.appName ===
          'LIVE-STATUS-SCREEN' || route.path.includes('/live-status');

      if (isLiveStatusRoute) {
        const routeName = String(route.name || '');
        const isGlobalView = routeName === 'live-status-global';
        const isDetailedView = routeName === 'live-status-detailed';

        // Prefer explicit gapDesc on node.meta, otherwise fall back to gapId
        const gapDescFromNode = selectedNode.value.meta?.gapDesc;
        const gapIdFromNode = selectedNode.value.meta?.gapId;
        const gapIdFromRoute =
          route.meta?.paramName === 'gapId'
            ? route.params[
                (route.meta?.paramName as string) ||
                  properties.routeParamName ||
                  'resourceId'
              ]
            : undefined;
        let gapDesc: string | undefined;
        if (gapDescFromNode) {
          gapDesc = gapDescFromNode;
        } else if (gapIdFromNode) {
          gapDesc = String(gapIdFromNode);
        } else if (gapIdFromRoute) {
          gapDesc = String(gapIdFromRoute);
        }
        if (gapDesc) {
          if (isGlobalView) {
            return {
              resourceName: '',
              gapDesc,
            };
          }

          if (isDetailedView) {
            return {
              resourceName: label,
              gapDesc,
            };
          }

          return {
            resourceName: label,
            gapDesc,
          };
        }

        if (isGlobalView) {
          return {
            resourceName: '',
          };
        }
      }

      return {
        resourceName: label,
      };
    }

    return {
      resourceName: t('SELECT_FROM_PLANT_TREE'),
    };
  });

  // Watch for route changes and trigger API calls
  watch(
    () => {
      const parameterName =
        (route.meta?.paramName as string) ||
        properties.routeParamName ||
        'resourceId';
      return route.params[parameterName];
    },
    async (newParameterValue, oldParameterValue) => {
      if (
        newParameterValue &&
        treeData.value.length > 0 &&
        typeof newParameterValue === 'string' &&
        newParameterValue !== oldParameterValue
      ) {
        isSelectingFromRoute.value = true;
        const parameterName = (route.meta?.paramName as string) || 'resourceId';

        try {
          // First validate if resource exists in current tree data
          const resourceExists = checkResourceIdExists(
            treeData.value,
            newParameterValue,
            parameterName,
          );
          if (!resourceExists) {
            console.warn(
              '[useTreeSelector] Route resource not found in API data:',
              newParameterValue,
            );

            // Show error message based on parameter type
            if (parameterName === 'gapId') {
              notify?.error({
                message: t('GAP_NOT_FOUND_FOR_PLANT'),
                title: t('GAP_NOT_FOUND'),
              });
            } else {
              notify?.error({
                message: t('RESOURCE_NOT_FOUND_FOR_PLANT'),
                title: t('RESOURCE_NOT_FOUND'),
              });
            }

            await router.push(properties.basePath || '/epb-ui');
            return;
          }

          // Check if resource is available in the current tree structure
          const resourceNode = findResourceNode(
            treeData.value,
            newParameterValue,
            parameterName,
          );
          if (resourceNode) {
            selectedNode.value = resourceNode;
            // Trigger hierarchy store update and API calls for route changes
            selectNode(resourceNode);
          } else {
            console.warn(
              '[useTreeSelector] Route resource in API but not in tree:',
              newParameterValue,
            );

            // Show error message based on parameter type
            if (parameterName === 'gapId') {
              notify?.error({
                message: t('GAP_NOT_ACCESSIBLE'),
                title: t('GAP_NOT_FOUND'),
              });
            } else {
              notify?.error({
                message: t('RESOURCE_NOT_ACCESSIBLE'),
                title: t('RESOURCE_NOT_FOUND'),
              });
            }

            await router.push(properties.basePath || '/epb-ui');
          }
        } catch (error) {
          console.error('[useTreeSelector] Route change error:', error);
          notify?.error({
            message: t('URL_PROCESSING_ERROR'),
            title: t('ERROR'),
          });
          await router.push(properties.basePath || '/epb-ui');
        } finally {
          isSelectingFromRoute.value = false;
        }
      } else if (!newParameterValue && oldParameterValue) {
        // ID was removed from URL - clear selection
        selectedNode.value = undefined;
      }
    },
  );

  // Watch for search query changes to auto-expand nodes when searching
  watch(searchQuery, (newQuery) => {
    if (newQuery.trim()) {
      expandedNodesBeforeSearch.value ??= new Set(expandedNodes.value);
      expandAllNodes();
      return;
    }

    if (expandedNodesBeforeSearch.value) {
      expandedNodes.value = new Set(expandedNodesBeforeSearch.value);
      expandedNodesBeforeSearch.value = null;
    }
  });

  return {
    clearSearch,
    displayText,
    filteredTreeData,
    isLoading,
    isNodeExpanded,
    loadData,
    searchQuery,
    selectNode,
    selectedNode,
    toggleNode,
    treeData,
  };
}

import axios, { type AxiosResponse } from 'axios';

/* =========================================================
 * ENV
 * ========================================================= */
const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

/* =========================================================
 * TYPES
 * ========================================================= */

export interface GetAlertCountsForResourcesDto {
  plant: string;
  workcenters: Array<string>;
  shiftStartDate?: string;
  shiftEndDate?: string;
  timezone?: string;
}

export interface GetAlertDetailsForResourcesDto {
  plant: string;
  workcenterIds: Array<string>;
}

export interface GetAlertDetailForResourcesDto {
  plant: string;
  resourceIds: Array<string>;
  timezone?: string;
}

export interface AlertByWorkcentersDetailsResponseDto {
  alertId: string;
  material: string;
  workcenterId: string;
  workcenterDescription?: string;
  startPickingTime?: string;
  newPromiseTime?: string;
  od?: string;
  endPreparation?: string;
  truckDeparture?: string;
  alertStatus: string;
  alertLevel: 'RED' | 'ORANGE' | 'YELLOW' | 'GREY';
  wkId: string;
}

/* =========================================================
 * HELPERS — snake_case → camelCase
 * (same philosophy as Management Control)
 * ========================================================= */

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param key - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) =>
        segment ? segment.charAt(0).toUpperCase() + segment.slice(1) : '',
      )
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }

  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};

  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }

  return result;
}

/* =========================================================
 * NORMALIZER HELPERS
 * ========================================================= */

/**
 * Extracts workcenterId from alert item, prioritizing 'workcenterId' field.
 * Backend may return 'workcenter' or 'workcenterId', so we check both.
 * @param item - The alert item object with unknown structure.
 * @returns Trimmed workcenterId string, or empty string if neither field exists.
 */
function resolveWorkcenterId(item: Record<string, unknown>): string {
  if (typeof item.workcenterId === 'string') {
    return item.workcenterId.trim();
  }

  if (typeof item.workcenter === 'string') {
    return item.workcenter.trim();
  }

  return '';
}

/* =========================================================
 * NORMALIZER
 * ========================================================= */

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param raw - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function normalizeAlertByWorkcentersResponse(
  raw: unknown,
): Array<AlertByWorkcentersDetailsResponseDto> {
  const camel = toCamelCaseDeep(raw);

  if (!Array.isArray(camel)) {
    return [];
  }

  return camel
    .filter((item): item is Record<string, unknown> =>
      item !== null && typeof item === 'object',
    )
    .map((item) => ({
      ...(item as unknown as AlertByWorkcentersDetailsResponseDto),
      workcenterId: resolveWorkcenterId(item),
    }));
}

/* =========================================================
 * API — MAIN FUNCTION
 * ========================================================= */

export const getAlertByWorkcentersDetails = async (
  dto: GetAlertDetailForResourcesDto,
): Promise<Array<AlertByWorkcentersDetailsResponseDto>> => {
  const headers: Record<string, string> = {
    contentType: 'application/json',
  };

  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  const response: AxiosResponse<AlertByWorkcentersDetailsResponseDto> =
    await axios.post(
      `${edashboardBackendBaseUrl}/egap-board/alert-details-for-resources`,
      dto,
      { headers },
    );
  return normalizeAlertByWorkcentersResponse(response.data);
};

import type { TreeNodeType } from '@/types/tree-select.types'

/**
 * Raw GAP item returned by the gap-mlean-list endpoint.
 */
export interface GapMleanItem {
  id: string | number;
  name?: string;
  [key: string]: unknown;
}

/**
 * Transform an array of raw GAP items into flat TreeNodeType nodes
 * suitable for the TreeSelector component.
 */
export function transformGapListToTree(
  gaps: Array<GapMleanItem>,
): Array<TreeNodeType> {
  return gaps.map((gap) => {
    const gapId = String(gap.id);
    const gapName = gap.name ? String(gap.name) : gapId;

    return {
      id: gapId,
      label: gapName,
      value: gapId,
      meta: {
        gapId,
        gapDesc: gapName,
      },
    };
  });
}

import axios, { AxiosResponse } from 'axios';
import type { ResourceMeta } from '@/global-components/TreeSelector/types';
import type {
  OptionalId,
  ApiResource,
  ApiWorkcenter,
  ApiProductionLine,
  ApiUap,
  ApiPlant,
} from '@/types/hierarchy.types';
import { Plant } from '@/types/plant';
import type { TreeNodeType } from '@/types/tree-select.types';
import appLogger from '@/utils/logger/app-logger';

export type { ApiPlant } from '@/types/hierarchy.types';
// ...existing code...

export class HierarchyService {
  public static transformApiToTree(
    apiData: Array<ApiPlant>,
  ): Array<TreeNodeType> {
    try {
      const result = apiData.map((plant, plantIndex) => {
        const plantNode: TreeNodeType = {
          id: plant.plantId ?? plantIndex,
          label: plant.plantDesc ?? `Plant ${plantIndex + 1}`,
          value: String(plant.plantId ?? plantIndex),
          children: this.transformUapsToTree(plant.uaps ?? [], plant.plantId),
        };

        return plantNode;
      });

      return result;
    } catch (error) {
      throw new Error(
        `Failed to transform API data to tree structure: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
  }

  public static transformApiToGapResourceTree(
    apiData: Array<ApiPlant>,
  ): Array<TreeNodeType> {
    const gapMap = new Map<string, TreeNodeType>();

    for (const plant of apiData) {
      this.populateGapMapFromPlant(plant, gapMap);
    }

    return this.finalizeGapNodes(gapMap);
  }

  private static populateGapMapFromPlant(
    plant: ApiPlant,
    gapMap: Map<string, TreeNodeType>,
  ): void {
    const plantId = plant.plantId;

    for (const uap of plant.uaps ?? []) {
      for (const productionLine of uap.productionLines ?? []) {
        for (const workcenter of productionLine.workcenters ?? []) {
          this.processResourcesForGapMap(
            workcenter.resources ?? [],
            gapMap,
            plantId,
          );
        }
      }
    }
  }

  private static processResourcesForGapMap(
    resources: Array<ApiResource>,
    gapMap: Map<string, TreeNodeType>,
    plantId: OptionalId,
  ): void {
    resources.forEach((resource) => {
      const gapId = this.extractValidGapId(resource.gapId);
      if (!gapId) {
        return;
      }

      const gapLabel = resource.gapDesc?.trim() || gapId;
      this.ensureGapNodeExists(gapMap, gapId, gapLabel, plantId);

      const gapNode = gapMap.get(gapId);
      if (!gapNode) {
        return;
      }

      this.addResourceToGapNode(
        gapNode,
        resource,
        gapId,
        gapLabel,
        plantId,
      );
    });
  }

  private static extractValidGapId(rawGapId: unknown): string | null {
    if (typeof rawGapId === 'string' || typeof rawGapId === 'number') {
      const id = String(rawGapId).trim();
      return id || null;
    }
    return null;
  }

  private static ensureGapNodeExists(
    gapMap: Map<string, TreeNodeType>,
    gapId: string,
    gapLabel: string,
    plantId: OptionalId,
  ): void {
    if (!gapMap.has(gapId)) {
      gapMap.set(gapId, {
        id: gapId,
        label: gapLabel,
        value: gapId,
        children: [],
        meta: {
          gapId,
          gapDesc: gapLabel,
          plantId,
        },
      });
    }
  }

  private static addResourceToGapNode(
    gapNode: TreeNodeType,
    resource: ApiResource,
    gapId: string,
    gapLabel: string,
    plantId: OptionalId,
  ): void {
    const resourceId = this.extractValidResourceId(resource.resourceId);
    if (!resourceId) {
      return;
    }

    if (this.resourceExistsInNode(gapNode, resourceId)) {
      return;
    }

    const children = (gapNode.children ??= []);
    children.push({
      id: resourceId,
      label: resource.resourceName ?? resourceId,
      value: resourceId,
      meta: {
        gapId,
        gapDesc: gapLabel,
        plantId: resource.plantId ?? plantId,
        productionLineId: resource.productionLineId,
        resourceId,
        uapId: resource.uapId,
        workcenterId: resource.workcenterId,
      },
    });
  }

  private static extractValidResourceId(
    resourceId: unknown,
  ): string | null {
    if (typeof resourceId === 'string' || typeof resourceId === 'number') {
      const id = String(resourceId).trim();
      return id || null;
    }
    return null;
  }

  private static resourceExistsInNode(
    gapNode: TreeNodeType,
    resourceId: string,
  ): boolean {
    return (gapNode.children ?? []).some(
      (child) => String(child.value) === resourceId,
    );
  }

  private static finalizeGapNodes(
    gapMap: Map<string, TreeNodeType>,
  ): Array<TreeNodeType> {
    const grouped = Array.from(gapMap.values()).sort((a, b) =>
      (a.label || '').localeCompare(b.label || ''),
    );

    for (const gapNode of grouped) {
      this.addResourceCountToNode(gapNode);
    }

    return grouped;
  }

  private static addResourceCountToNode(gapNode: TreeNodeType): void {
    const count = Array.isArray(gapNode.children)
      ? gapNode.children.length
      : 0;

    gapNode.meta = {
      ...gapNode.meta,
      gapResourceCount: count,
    };

    (gapNode.children ?? []).forEach((child) => {
      child.meta = {
        ...(child.meta),
        gapResourceCount: count,
      };
    });
  }

  private static transformUapsToTree(
    uaps: Array<ApiUap>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    return uaps.map((uap, uapIndex) => ({
      children: this.transformProductionLinesToTree(
        uap.productionLines ?? [],
        plantId,
      ),
      id: uap.uapId ?? uapIndex,
      label: uap.uapDesc ?? '',
      value: String(uap.uapId ?? ''),
    }));
  }

  private static transformProductionLinesToTree(
    productionLines: Array<ApiProductionLine>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    return productionLines.map((productionLine, productionIndex) => ({
      id: productionLine.prodLineId ?? productionIndex,
      label: productionLine.prodLineDesc ?? '',
      value: String(productionLine.prodLineId ?? ''),
      children: this.transformWorkcentersToTree(
        productionLine.workcenters ?? [],
        plantId,
      ),
    }));
  }

  private static transformWorkcentersToTree(
    workcenters: Array<ApiWorkcenter>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    return workcenters.map((wc, wcIndex) => ({
      children: this.transformResourcesToTree(wc.resources ?? [], plantId),
      id: wc.workcenterId ?? wcIndex,
      label: wc.workcenterDesc ?? '',
      value: String(wc.workcenterId ?? ''),
    }));
  }

  private static transformResourcesToTree(
    resources: Array<ApiResource>,
    plantId?: OptionalId,
  ): Array<TreeNodeType> {
    try {
      const result = resources.map((resource, resourceIndex) => {
        // Ensure we have a valid resourceId, use fallback if needed
        const resourceId = resource.resourceId ?? `resource_${resourceIndex}`;
        const resourceName =
          resource.resourceName ??
          String(resource.resourceId ?? `Resource ${resourceIndex + 1}`);

        const resourceNode: TreeNodeType = {
          id: resourceId,
          label: resourceName,
          value: String(resourceId),
          meta: {
            gapDesc: resource.gapDesc,
            gapId: resource.gapId,
            plantId: resource.plantId ?? plantId, // Use resource-specific plantId if available, otherwise inherit from parent plant
            productionLineId: resource.productionLineId,
            resourceId,
            uapId: resource.uapId,
            workcenterId: resource.workcenterId,
          } as ResourceMeta,
        };

        return resourceNode;
      });

      return result;
    } catch (error) {
      appLogger.error(
        '[HierarchyService] Error transforming resources:',
        String(error),
      );
      throw new Error(
        `Failed to transform resources: ${error instanceof Error ? error.message : 'Unknown error'}`,
      );
    }
  }

  public static filterTreeByResource(
    nodes: Array<TreeNodeType>,
    resourceId: string,
  ): Array<TreeNodeType> {
    return nodes
      .map((node) => {
        if (node.children && node.children.length > 0) {
          const filteredChildren = this.filterTreeByResource(
            node.children,
            resourceId,
          );
          if (filteredChildren.length > 0) {
            return { ...node, children: filteredChildren };
          }
          return;
        }
        // Check if this is a resource node matching the resourceId
        if (!node.children && node.value === resourceId) {
          return node;
        }
      })
      .filter((node): node is TreeNodeType => node !== undefined);
  }

  public static findNodePath(
    nodes: Array<TreeNodeType>,
    targetValue: string,
  ): unknown {
    for (const node of nodes) {
      if (node.value === targetValue && !node.children) {
        return { resource: node.label };
      }
      if (node.children && node.children.length > 0) {
        const childPath = this.findNodePath(node.children, targetValue);
        if (childPath) {
          return {
            [this.getNodeLevel(node)]: node.label,
            ...childPath,
          };
        }
      }
    }
    return undefined;
  }

  private static getNodeLevel(node: TreeNodeType): string {
    // Determine the level based on node structure
    // This is a simplified version - you might need more sophisticated logic
    if (
      node.children?.some((child) =>
        child.children?.some((gc) => gc.children?.some((ggc) => !ggc.children)),
      )
    ) {
      return 'plant';
    }
    if (
      node.children?.some((child) => child.children?.some((gc) => !gc.children))
    ) {
      return 'uap';
    }
    if (node.children?.some((child) => !child.children)) {
      return 'productionLine';
    }
    if (node.children && node.children.length > 0) {
      return 'workcenter';
    }
    return 'resource';
  }

  public static findResourceByGapId(
    apiData: Array<ApiPlant>,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    for (const plant of apiData) {
      const result = this.searchGapIdInPlant(plant, gapId);
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInPlant(
    plant: ApiPlant,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!plant.uaps) {
      return undefined;
    }

    for (const uap of plant.uaps) {
      const result = this.searchGapIdInUap(uap, plant.plantId, gapId);
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInUap(
    uap: ApiUap,
    plantId: OptionalId,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!uap.productionLines) {
      return undefined;
    }

    for (const productionLine of uap.productionLines) {
      const result = this.searchGapIdInProductionLine(
        productionLine,
        plantId,
        uap.uapId,
        gapId,
      );
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInProductionLine(
    productionLine: ApiProductionLine,
    plantId: OptionalId,
    uapId: OptionalId,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!productionLine.workcenters) {
      return undefined;
    }

    for (const wc of productionLine.workcenters) {
      const result = this.searchGapIdInWorkcenter(
        wc,
        plantId,
        uapId,
        productionLine.prodLineId,
        gapId,
      );
      if (result) {
        return result;
      }
    }
    return undefined;
  }

  private static searchGapIdInWorkcenter(
    wc: ApiWorkcenter,
    plantId: OptionalId,
    uapId: OptionalId,
    productionLineId: OptionalId,
    gapId: string,
  ): { resourceId: string; resourceNode: TreeNodeType } | undefined {
    if (!wc.resources) {
      return undefined;
    }

    for (const resource of wc.resources) {
      if (resource.gapId === gapId) {
        return this.createResourceResult(
          resource,
          plantId,
          uapId,
          productionLineId,
          wc.workcenterId,
        );
      }
    }
    return undefined;
  }

  private static createResourceResult(
    resource: ApiResource,
    plantId: OptionalId,
    uapId: OptionalId,
    productionLineId: OptionalId,
    workcenterId: OptionalId,
  ): { resourceId: string; resourceNode: TreeNodeType } {
    const resourceNode: TreeNodeType = {
      id: resource.resourceId ?? '',
      label: resource.resourceName ?? '',
      value: String(resource.resourceId ?? ''),
      meta: {
        gapDesc: resource.gapDesc,
        gapId: resource.gapId,
        plantId,
        productionLineId,
        resourceId: resource.resourceId,
        uapId,
        workcenterId,
      } as ResourceMeta,
    };
    return {
      resourceId: String(resource.resourceId),
      resourceNode,
    };
  }

  private readonly baseUrl: string;

  private readonly token: string;

  public getHierarchy = async (): Promise<Array<Plant>> => {
    const userId = localStorage.getItem('userId');
    const response: AxiosResponse = await axios.get(
      `${this.baseUrl}/epart-board/getHierarchy/${userId}`,
      { headers: { authorization: `Bearer ${this.token}` } },
    );
    return response.data;
  };

  public constructor(baseUrl: string, authToken?: string) {
    this.baseUrl = baseUrl;
    this.token = authToken || '';
  }
}

import type {
  CheckpointResult,
  GetManagementControlQuery,
  ManagementControlApiResponse,
  ManagementControlCheckpoint,
} from '@/types/management-control-api.types';
import type {
  ControlIndicatorStatus,
  ManagementControlCard,
} from '@/types/management-control.types';

const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

/**
 * Converts a snake_case key to camelCase.
 * @param key - Key name to convert.
 * @returns camelCased key.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) => {
        if (!segment) {
          return '';
        }
        return segment.charAt(0).toUpperCase() + segment.slice(1);
      })
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }
  return result;
}

/**
 * Processes checkpoint results array from raw data.
 * @param resultsRaw - Raw checkpoint results data.
 * @returns Array of processed checkpoint results.
 */
function processCheckpointResults(
  resultsRaw: unknown,
): Array<CheckpointResult> {
  if (!Array.isArray(resultsRaw)) {
    return [];
  }

  const results: Array<CheckpointResult> = [];
  for (const resultItem of resultsRaw) {
    if (resultItem && typeof resultItem === 'object') {
      const { label, status } = resultItem as {
        label?: unknown;
        status?: unknown;
      };

      if (typeof label === 'string' && typeof status === 'string') {
        results.push({
          label,
          status: status as CheckpointResult['status'],
        });
      }
    }
  }

  return results;
}

/**
 * Processes a single management control item from raw data.
 * @param record - Raw record data.
 * @returns Processed management control checkpoint or null if invalid.
 */
function processManagementControlItem(
  record: Record<string, unknown>,
): ManagementControlCheckpoint | undefined {
  const idRaw = record.id;
  const id = typeof idRaw === 'number' ? idRaw : Number(idRaw);

  if (!Number.isFinite(id)) {
    return undefined;
  }

  const results = processCheckpointResults(record.checkpointResults);
  const labelIsDashOrOk = Boolean(
    record.labelIsDashOrOk ?? record.labelIsDashorOK,
  );

  return {
    checkpointCategoryColor:
      typeof record.checkpointCategoryColor === 'string'
        ? record.checkpointCategoryColor
        : '',
    checkpointCategoryDescription:
      typeof record.checkpointCategoryDescription === 'string'
        ? record.checkpointCategoryDescription
        : '',
    checkpointDescription:
      typeof record.checkpointDescription === 'string'
        ? record.checkpointDescription
        : '',
    checkpointResults: results,
    id,
    labelIsDashOrOk,
  };
}

/**
 * Normalizes backend response (snake_case) to camelCase DTO.
 * @param raw - Raw response payload from backend.
 * @returns Normalized management control API response.
 */
function normalizeManagementControlApiResponse(
  raw: unknown,
): ManagementControlApiResponse {
  const camel = toCamelCaseDeep(raw);
  if (!Array.isArray(camel)) {
    return [];
  }

  const normalized: Array<ManagementControlCheckpoint> = [];

  for (const item of camel) {
    if (item && typeof item === 'object') {
      const record = item as Record<string, unknown>;
      const processed = processManagementControlItem(record);

      if (processed) {
        normalized.push(processed);
      }
    }
  }

  return normalized;
}

/**
 * Fetches management control details from the API.
 * @param query - The query parameters for fetching management control data.
 * @returns Promise resolving to management control API response.
 */
export async function fetchManagementControlDetails(
  query: GetManagementControlQuery,
): Promise<ManagementControlApiResponse> {
  const parameters = new URLSearchParams({
    plant: query.plant,
    shiftEndDate: query.shiftEndDate,
    shiftStartDate: query.shiftStartDate,
    team: query.team,
    ...(query.timezone ? { timezone: query.timezone } : {}),
  });

  const url = `${edashboardBackendBaseUrl}/egap-board/management-control-details?${parameters.toString()}`;

  const headers = new Headers();
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('authorization', `Bearer ${token}`);
  }

  const response = await fetch(url, {
    credentials: 'include',
    headers,
    method: 'GET',
  });

  if (!response.ok) {
    throw new Error(
      `Failed to fetch management control details: ${response.statusText}`,
    );
  }

  let rawData: unknown;
  if (response.status !== 204) {
    try {
      rawData = await response.json();
    } catch {
      rawData = undefined;
    }
  }

  return normalizeManagementControlApiResponse(rawData);
}

/**
 * Maps API status string to control indicator status.
 * @param apiStatus - The status string from the API (green, red, gray).
 * @returns The corresponding control indicator status.
 */
function mapApiStatusToIndicatorStatus(
  apiStatus: string,
): ControlIndicatorStatus {
  switch (apiStatus.toLowerCase()) {
    case 'green': {
      return 'valid';
    }
    case 'red': {
      return 'invalid';
    }
    case 'gray':
    case 'grey': {
      return 'pending';
    }
    default: {
      return 'na';
    }
  }
}

/**
 * Transforms API response to management control card format.
 * @param apiResponse - The raw API response data.
 * @returns Array of management control cards.
 */
export function transformApiResponseToCards(
  apiResponse: ManagementControlApiResponse,
): Array<ManagementControlCard> {
  return apiResponse.map((checkpoint) => ({
    category: checkpoint.checkpointCategoryDescription?.trim() || 'Other',
    categoryIconColor: checkpoint.checkpointCategoryColor,
    categoryLabel: checkpoint.checkpointCategoryDescription?.trim() || 'Other',
    id: String(checkpoint.id),
    indicators: checkpoint.checkpointResults.map((result) => ({
      label: result.label,
      status: mapApiStatusToIndicatorStatus(result.status),
    })),
    title: checkpoint.checkpointDescription,
  }));
}

