import type {
  PageLayoutDocument,
  GetLayoutResponse,
} from '@/types/page-layout-config.types';
import appLogger from '@/utils/logger/app-logger';

// ─── Configuration ───────────────────────────────────────────────────────────
/**
 * Admin backend base URL for page layout endpoints.
 */
const adminBackendBaseUrl = import.meta.env.ADMIN_BACKEND_URL;
const token = import.meta.env.TOKEN;

// ─── API Endpoints ───────────────────────────────────────────────────────────
const ENDPOINTS = {
  /** Get layout by scope (POST) */
  layoutByScope: 'page-builder/templates/scope',
  /**
   * Get default layout by plant (GET)
   * @param plant The plant ID used by the default-template endpoint.
   * @returns The endpoint path for fetching default layout
   */
  defaultLayoutByPlant: (plant: number) =>
    `page-builder/templates/default/${plant}`,
} as const;

// ─── Helper Functions ────────────────────────────────────────────────────────

/**
 * Creates standard headers for API requests.
 * @returns Headers object with Content-Type and Authorization (if token is available)
 */
function createHeaders(): Headers {
  const headers = new Headers();
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('Authorization', `Bearer ${token}`);
  }
  return headers;
}

/**
 * Builds URL with query parameters.
 * @param path - API endpoint path
 * @param parameters - Optional query parameters as key-value pairs
 * @returns Full URL string with query parameters appended
 */
function buildUrl(path: string, parameters?: Record<string, unknown>): string {
  // Ensure base URL ends with / so relative paths append correctly
  const baseUrl = adminBackendBaseUrl.endsWith('/')
    ? adminBackendBaseUrl
    : `${adminBackendBaseUrl}/`;
  const url = new URL(path, baseUrl);

  if (parameters) {
    for (const [key, value] of Object.entries(parameters)) {
      // Only convert primitives to strings; skip objects and arrays
      if (
        value !== undefined &&
        value !== null &&
        (typeof value === 'string' ||
          typeof value === 'number' ||
          typeof value === 'boolean')
      ) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  return url.toString();
}

/**
 * Normalizes a single part of a component code.
 * @param part Single part of the code to normalize
 * @returns Normalized part in camelCase
 */
const normalizePart = (part: string): string => {
  let result = '';
  for (const [index, character] of [...part].entries()) {
    const previous = part[index - 1];
    const next = part[index + 1];
    const shouldInsertSeparator =
      index > 0 &&
      character >= 'A' &&
      character <= 'Z' &&
      ((previous >= 'a' && previous <= 'z') ||
        (previous >= '0' && previous <= '9') ||
        (previous >= 'A' && previous <= 'Z' && next >= 'a' && next <= 'z'));

    result = `${result}${shouldInsertSeparator ? '_' : ''}${character}`;
  }

  const parts = result.split('_');
  return (
    parts[0].toLowerCase() +
    parts
      .slice(1)
      .map(
        (piece: string) =>
          piece.charAt(0).toUpperCase() + piece.slice(1).toLowerCase(),
      )
      .join('')
  );
};

/**
 * Normalizes component codes from PascalCase/snake_case to camelCase.
 * This ensures API responses with different naming conventions work with the renderer registry.
 * @param code Component code from JSON config
 * @returns Normalized camelCase code
 */
function normalizeComponentCode(code: string): string {
  const trimmed = code.trim();
  if (!trimmed) return code;

  const parts = trimmed
    .split('_')
    .filter(Boolean)
    .map((part) => normalizePart(part));
  if (parts.length === 0) return '';

  return (
    parts[0] +
    parts
      .slice(1)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join('')
  );
}

/**
 * Recursively normalizes component codes in layout sections and widgets.
 * @param layout Layout document to normalize
 */
function normalizeLayoutComponentCodes(layout: PageLayoutDocument): void {
  if (!layout.devices) return;

  interface Widget {
    component?: { code: string };
    components?: Array<Widget>;
  }

  interface Section {
    widgets?: Array<Widget>;
  }

  interface Device {
    layout?: { sections: Array<Section> };
  }

  const normalizeWidget = (widget: Widget): void => {
    const normalizedWidget = widget;
    if (normalizedWidget?.component?.code) {
      normalizedWidget.component.code = normalizeComponentCode(
        normalizedWidget.component.code,
      );
    }
    if (Array.isArray(normalizedWidget?.components)) {
      for (const child of normalizedWidget.components) {
        normalizeWidget(child);
      }
    }
  };

  const normalizeSections = (sections: Array<Section>): void => {
    for (const section of sections) {
      if (Array.isArray(section?.widgets)) {
        for (const widget of section.widgets) {
          normalizeWidget(widget);
        }
      }
    }
  };

  for (const device of Object.values(layout.devices)) {
    const typedDevice = device as Device;
    if (typedDevice?.layout?.sections) {
      normalizeSections(typedDevice.layout.sections);
    }
  }
}

/**
 * Parses and validates the layout response body.
 * @param text - Raw response text
 * @returns Parsed layout document
 */
function parseLayoutResponse(text: string): PageLayoutDocument {
  if (!text) {
    throw new Error('API returned empty response body');
  }

  const fullResponse = JSON.parse(text);

  // Verify the layout structure exists in the response
  const layout = fullResponse.devices?.desktop?.layout;

  if (!layout) {
    console.error(
      '[DEBUG] Layout not found. Response structure:',
      fullResponse,
    );
    throw new Error('Layout not found in response structure');
  }

  // Normalize all component codes to match renderer registry
  normalizeLayoutComponentCodes(fullResponse);

  return fullResponse as PageLayoutDocument;
}

// ─── Page Layout API Service ─────────────────────────────────────────────────
/**
 * Service for interacting with the admin-backend page layout API.
 *
 * NOTE: These endpoints are not yet available.
 * The service is prepared for when the backend is ready.
 * Currently, the UI uses mock data from mock-page-layout.ts.
 */
export const pageLayoutApiService = {
  /**
   * Fetches layout by scope using POST method.
   * This is the primary method to get a layout for a specific resource/workcenter.
   * @param plant - The plant ID
   * @param scopeType - The scope type (e.g., "Resource", "Workcenter")
   * @param scopeValue - The scope value (e.g., "Resource1")
   * @param screenId The Page Builder screen ID used to avoid cross-screen template matches.
   * @returns Promise with the layout document
   * @example
   * ```typescript
   * const response = await pageLayoutApiService.getLayoutByScope(1001, 'Resource', 'Resource1');
   * if (response.success) {
   *   console.log(response.data);
   * }
   * ```
   */
  async getLayoutByScope(
    plant: number,
    scopeType: string,
    scopeValue: string,
    screenId?: number,
  ): Promise<GetLayoutResponse> {
    const url = buildUrl(ENDPOINTS.layoutByScope);

    const body = {
      plant,
      screenId,
      scopeType,
      scopeValue,
    };

    try {
      const response = await fetch(url, {
        body: JSON.stringify(body),
        headers: createHeaders(),
        method: 'POST',
      });

      if (!response.ok) {
        const errorText = await response.text().catch(() => 'Unknown error');
        throw new Error(`API Error (${response.status}): ${errorText}`);
      }

      let text = '';
      try {
        text = await response.text();
      } catch (textError) {
        console.error('[DEBUG] Error reading response text:', textError);
        throw new Error(`Failed to read response body: ${textError}`);
      }

      const fullResponse = parseLayoutResponse(text);

      // Return the full response as PageLayoutDocument
      // The store expects the nested devices.desktop.layout structure
      return {
        data: fullResponse,
        success: true,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      console.warn('[PageLayoutApi] Error fetching layout by scope:', message);
      console.warn('[DEBUG] Full error:', error);

      return {
        success: false,
        message,
      };
    }
  },

  /**
   * Fetches the default layout for a plant using GET method.
   * @param screenId The Page Builder screen ID used to fetch the matching default template.
   * @returns Promise with the layout document
   */
  async getDefaultLayout(screenId?: number): Promise<GetLayoutResponse> {
    const DEFAULT_PLANT = 0; // Assuming 0 is the default plant ID; adjust as needed
    const url = buildUrl(ENDPOINTS.defaultLayoutByPlant(DEFAULT_PLANT), {
      screenId,
    });
    try {
      const response = await fetch(url, {
        headers: createHeaders(),
        method: 'GET',
      });
      if (!response.ok) {
        const errorText = await response.text().catch(() => 'Unknown error');
        throw new Error(`API Error (${response.status}): ${errorText}`);
      }

      let text = '';
      try {
        text = await response.text();
      } catch (textError) {
        console.error('[DEBUG] Error reading response text:', textError);
        throw new Error(`Failed to read response body: ${textError}`);
      }

      const fullResponse = parseLayoutResponse(text);
      return {
        data: fullResponse,
        success: true,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      appLogger.error(
        '[PageLayoutApi] Error fetching default layout:',
        message,
      );
      console.warn('[DEBUG] Full error:', error);

      return {
        success: false,
        message,
      };
    }
  },
};

// Export type for dependency injection in tests
export type PageLayoutApiServiceType = typeof pageLayoutApiService;

