  });

  if (!response.ok) {
    throw new Error(`Failed to fetch plant config: ${response.statusText}`);
  }

  const raw = (await response.json()) as unknown;
  if (!raw || typeof raw !== 'object') {
    return {};
  }

  const record = raw as Record<string, unknown>;
  const { mleanLink } = record;

  return {
    mleanLink: typeof mleanLink === 'string' ? mleanLink : undefined,
  };
}

import { PolyvalenceQuery, PolyvalenceResponse } from '@/types/polyvalence.types';
