/**
 * Fetches and parses the team list for a given plant from the backend.
 * @param query - The query param.
 * @returns Sorted array of team options.
 */
export async function fetchPolyvalenceDetails(
 query: PolyvalenceQuery,
): Promise<PolyvalenceResponse> {
  const plant = encodeURIComponent(query.plant);
  const perimeter = encodeURIComponent(query.gap);
  const team = encodeURIComponent(String(query.team));

  const headers: Record<string, string> = {};
  headers['Content-Type'] = 'application/json';
  if (token) {
    headers.authorization = `Bearer ${token}`;
  }

  let raw: unknown;
  try {
    const response = await axios.get(
      `${edashboardBackendBaseUrl}/egap-board/polyvalence-information/${plant}/${perimeter}/${team}`,
      {
        headers,
        withCredentials: true,
      },
    );
    raw = response.data as unknown;
  } catch (error_) {
    const statusText =
      axios.isAxiosError(error_) && error_.response?.statusText
        ? error_.response.statusText
        : 'Request failed';
    throw new Error(`Failed to fetch teams: ${statusText}`);
  }
  return raw as PolyvalenceResponse;
}

