const token = import.meta.env.TOKEN;
const edashboardBackendBaseUrl = import.meta.env.EPART_BOARD_BACKEND_URL;

/**
 * Converts a snake_case key to camelCase.
 * @param key - Key name to convert.
 * @returns camelCased key.
 */
function toCamelCaseKey(key: string): string {
  const segments = key.split('_');
  if (segments.length <= 1) {
    return key;
  }

  const [first, ...rest] = segments;
  return (
    first +
    rest
      .map((segment) => {
        if (!segment) {
          return '';
        }
        return segment.charAt(0).toUpperCase() + segment.slice(1);
      })
      .join('')
  );
}

/**
 * Recursively converts all object keys from snake_case to camelCase.
 * @param value - Any JSON-like value.
 * @returns Value with all object keys camelCased.
 */
function toCamelCaseDeep(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((it) => toCamelCaseDeep(it));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const [rawKey, rawValue] of Object.entries(record)) {
    result[toCamelCaseKey(rawKey)] = toCamelCaseDeep(rawValue);
  }
  return result;
}

/**
 * Processes a single routine detail item from raw data.
 * @param record - Raw record data.
 * @returns Processed routine detail item or undefined if invalid.
 */
function processRoutineDetailItem(
  record: Record<string, unknown>,
): RoutineDetailItem | undefined {
  const scheduleEntryIdRaw = record.scheduleEntryId;
  const scheduleEntryId =
    typeof scheduleEntryIdRaw === 'number'
      ? scheduleEntryIdRaw
      : Number(scheduleEntryIdRaw);

  const scheduleIdRaw = record.scheduleId;
  const scheduleId =
    typeof scheduleIdRaw === 'number' ? scheduleIdRaw : Number(scheduleIdRaw);

  if (!Number.isFinite(scheduleEntryId) || !Number.isFinite(scheduleId)) {
    return undefined;
  }

  const description =
    typeof record.description === 'string' ? record.description : '';
  const status =
    record.status === 'OK' ||
    record.status === 'NOK' ||
    record.status === 'N/Ap' ||
    record.status === 'N/As'
      ? record.status
      : undefined;
  const color =
    record.color === 'green' ||
    record.color === 'red' ||
    record.color === 'gray' ||
    record.color === 'grey'
      ? record.color
      : 'red';

  if (!status) {
    return undefined;
  }

  return {
    color,
    description,
    scheduleEntryId,
    scheduleId,
    status,
  };
}

/**
 * Normalizes backend response (snake_case) to camelCase DTO.
 * @param raw - Raw response payload from backend.
 * @returns Normalized routine details API response.
 */
function normalizeRoutineDetailsApiResponse(
  raw: unknown,
): RoutineDetailsApiResponse {
  const camel = toCamelCaseDeep(raw);
  if (!Array.isArray(camel)) {
    return [];
  }

  const normalized: Array<RoutineDetailItem> = [];

  for (const item of camel) {
    if (item && typeof item === 'object') {
      const record = item as Record<string, unknown>;
      const processed = processRoutineDetailItem(record);

      if (processed) {
        normalized.push(processed);
      }
    }
  }

  return normalized;
}

/**
 * Fetches routine details from the API.
 * @param query - The query parameters for fetching routine details.
 * @returns Promise resolving to routine details API response.
 */
export async function fetchRoutineDetails(
  query: GetRoutineDetailsQuery,
): Promise<RoutineDetailsApiResponse> {
  const parameters = new URLSearchParams({
    plant: query.plant,
    shiftEndDate: query.shiftEndDate,
    shiftStartDate: query.shiftStartDate,
    team: query.team,
    ...(query.timezone ? { timezone: query.timezone } : {}),
  });

  const url = `${edashboardBackendBaseUrl}/egap-board/routine-details?${parameters.toString()}`;

  const headers = new Headers();
  headers.set('Content-Type', 'application/json');
  if (token) {
    headers.set('authorization', `Bearer ${token}`);
  }

  const response = await fetch(url, {
    credentials: 'include',
    headers,
    method: 'GET',
  });

  if (!response.ok) {
    throw new Error(`Failed to fetch routine details: ${response.statusText}`);
  }

  let rawData: unknown;
  if (response.status !== 204) {
    try {
      rawData = await response.json();
    } catch {
      rawData = undefined;
    }
  }

  return normalizeRoutineDetailsApiResponse(rawData);
}

/**
 * Transforms API response to routine card format.
 * @param apiResponse - The raw API response data.
 * @returns Array of routine cards.
 */
export function transformApiResponseToRoutineCards(
  apiResponse: RoutineDetailsApiResponse,
): Array<RoutineCard> {
  return apiResponse.map(
    (item): RoutineCard => ({
      color: item.color,
      description: item.description,
      id: `${item.scheduleEntryId}-${item.scheduleId}`,
      scheduleEntryId: item.scheduleEntryId,
      scheduleId: item.scheduleId,
      status: item.status,
    }),
  );
}

