/**
 * Page Layout Configuration Types
 *
 * Represents the JSON structure generated by the Page Builder,
 * stored in CosmosDB, fetched from admin-backend, and rendered by epb-ui.
 */

// ─── Scope ───────────────────────────────────────────────────────────────────
/**
 * Scope item in the scopeList array.
 * Represents a resource or workcenter that this layout applies to.
 */
export interface ScopeConfig {
  /** E.g., "Resource", "Workcenter" */
  scopeType: string;
  /** E.g., "Resource1", "Workcenter1" */
  scopeValue: string;
}

// ─── Screen ──────────────────────────────────────────────────────────────────
export interface ScreenConfig {
  screenId: string;
  screenName: string;
}

// ─── Widget Config Schema ────────────────────────────────────────────────────
/**
 * Widget-level config schema can be a string identifier or an object with settings.
 */
export type WidgetConfigSchema = string | Record<string, unknown>;

// ─── Component (from ume.Component table) ────────────────────────────────────
export interface ComponentConfig {
  /** Maps to a Vue component (ume.Component.code) */
  code: string;
  /** Editable title from JSON (ume.Component.label) */
  label: string;
  /** Config schema (ume.Component.config_schema) */
  configSchema: string;
  /** Default/preview value from Page Builder component metadata */
  defaultValue?: string;
  /** API endpoint to fetch data for the widget */
  api: string;
  /** Widget size in the layout */
  size: 'full' | 'half' | 'third' | 'quarter';
  /** Whether to show the label in the UI */
  showLabel?: boolean;
}

// ─── Widget ──────────────────────────────────────────────────────────────────
export interface WidgetConfig {
  id: string;
  /** Editable widget label from JSON */
  label: string;
  /** Config schema - can be string or object with settings */
  configSchema: WidgetConfigSchema;
  order: number;
  /** The component to render for this widget */
  component: ComponentConfig;
  /** Nested child components (for container widgets like KPISection) */
  components?: Array<WidgetConfig>;
}

// ─── Section ─────────────────────────────────────────────────────────────────
export interface SectionConfig {
  id: string;
  /** Editable section label from JSON */
  label: string;
  configSchema: string;
  order: number;
  /** Minimum number of widgets allowed in this section */
  minWidget: number;
  /** Maximum number of widgets allowed in this section */
  maxWidget: number;
  /** If true, section renders with a visible header/title */
  showHeader?: boolean;
  widgets: Array<WidgetConfig>;
}

// ─── Device Layout ───────────────────────────────────────────────────────────
export interface DeviceLayoutConfig {
  id: string;
  configSchema: string;
  /** Minimum number of sections allowed */
  minSection: number;
  /** Maximum number of sections allowed */
  maxSection: number;
  /** Layout width in pixels */
  width?: number;
  /** Layout height in pixels */
  height?: number;
  sections: Array<SectionConfig>;
}

// ─── Device Entry ────────────────────────────────────────────────────────────
export interface DeviceEntry {
  resolution: string;
  layout: DeviceLayoutConfig;
}

// ─── Devices ─────────────────────────────────────────────────────────────────
export interface DevicesConfig {
  desktop?: DeviceEntry;
  tablet?: DeviceEntry;
  mobile?: DeviceEntry;
}

// ─── Root Document (CosmosDB item) ───────────────────────────────────────────
export interface PageLayoutDocument {
  /** Document ID (template ID) */
  id: string;
  /** Display label for the layout */
  label: string;
  /** Plant ID this layout applies to */
  plant: number;
  /** Array of scopes this layout applies to */
  scopeList: Array<ScopeConfig>;
  /** Layout status */
  status: 'draft' | 'published' | 'archived';
  /** User who created this layout */
  createdBy: string;
  /** Creation timestamp (ISO-8601) */
  createdAt: string;
  /** User who last updated this layout */
  updatedBy: string;
  /** Last update timestamp (ISO-8601) */
  updatedAt: string;
  /** Whether this is the default layout for the scope */
  default: boolean;
  /** Array of screens this layout applies to */
  screens: Array<ScreenConfig>;
  /** Device-specific layout configurations */
  devices: DevicesConfig;
}

// ─── API Response Types ──────────────────────────────────────────────────────
/**
 * Response from the admin-backend when fetching a single layout.
 */
export interface GetLayoutResponse {
  data?: PageLayoutDocument;
  success: boolean;
