import type {
  TreeSelectorProperties,
  HierarchyPayload,
} from '@/types/tree-selector.types';
// ...existing code...

/**
 * Helper class to handle tree selections
 */
export class TreeSelector {
  private readonly router: Router;

  private readonly route: RouteLocationNormalizedLoaded;

  private readonly userAttributesStore: ReturnType<typeof useUserStore>;

  private readonly properties: TreeSelectorProperties;

  private readonly selectedNode: Ref;

  private readonly isSelectingFromRoute: Ref<boolean>;

  public constructor(
    router: Router,
    route: RouteLocationNormalizedLoaded,
    userAttributesStore: ReturnType<typeof useUserStore>,
    properties: TreeSelectorProperties,
    selectedNode: Ref,
    isSelectingFromRoute: Ref<boolean>,
  ) {
    this.router = router;
    this.route = route;
    this.userAttributesStore = userAttributesStore;
    this.properties = properties;
    this.selectedNode = selectedNode;
    this.isSelectingFromRoute = isSelectingFromRoute;
  }

  public select(node: TreeNodeType): void {
    if (!node) {
      appLogger.warn('[TreeSelector] Attempted to select null/undefined node');
      return;
    }

    try {
      this.selectedNode.value = node;

      this.updateHierarchyStore(node);

      if (!this.shouldUpdateRoute()) {
        return;
      }

      const isLiveStatusRoute = this.isLiveStatusRoute();
      const targetRouteName = this.resolveTargetRouteName(
        node,
        isLiveStatusRoute,
      );
      const routeParameter = this.resolveRouteParameter(
        node,
        targetRouteName,
        isLiveStatusRoute,
      );

      if (!routeParameter) {
        return;
      }

      this.pushRoute(targetRouteName, routeParameter.name, routeParameter.value);
    } catch (error) {
      appLogger.error(
        '[TreeSelector] Error during node selection:',
        String(error),
      );
      throw error;
    }
  }

  private updateHierarchyStore(node: TreeNodeType): void {
    if (!this.properties.hierarchyStore || !node.meta) {
      console.warn('[TreeSelector] Missing hierarchy store or node metadata');
      return;
    }

    const nodeMeta = node.meta as {
      plantId?: string | number;
      uapId?: string | number;
      productionLineId?: string | number;
      workcenterId?: string | number;
      resourceId?: string;
      gapId?: string | number | null;
    };

    const payload: HierarchyPayload = {
      gapId: nodeMeta.gapId ? String(nodeMeta.gapId) : undefined,
      plant: String(nodeMeta.plantId || this.getUserPlantAttribute() || ''),
      productionLine: String(nodeMeta.productionLineId || ''),
      resource: String(nodeMeta.resourceId || node.value || ''),
      uap: String(nodeMeta.uapId || ''),
      workcenter: String(nodeMeta.workcenterId || ''),
    };

    (
      this.properties.hierarchyStore as {
        setHierarchy: (payload: HierarchyPayload) => void;
      }
    )?.setHierarchy(payload);
  }

  private getUserPlantAttribute(): string | number | undefined {
    if (!Array.isArray(this.userAttributesStore.userAttributes)) {
      return undefined;
    }

    return this.userAttributesStore.userAttributes.find(
      (attribute) => attribute.userAttributeName === 'plant',
    )?.value;
  }

  private shouldUpdateRoute(): boolean {
    return !!this.route.name && !this.isSelectingFromRoute.value;
  }

  private isLiveStatusRoute(): boolean {
    return (
      (this.route.meta as { appName?: string })?.appName ===
        'LIVE-STATUS-SCREEN' || this.route.path.includes('/live-status')
    );
  }

  private resolveTargetRouteName(
    node: TreeNodeType,
    isLiveStatusRoute: boolean,
  ): string {
    let targetRouteName = this.normalizeDefaultRouteName(this.route.name as string);

    if (!isLiveStatusRoute) {
      return targetRouteName;
    }

    const isGapNode = !!node.meta?.gapId && !node.meta?.resourceId;
    const isResourceNode = !!node.meta?.resourceId;
    const children = Array.isArray(node.children) ? node.children : [];
    const gapResourceCount = Number(node.meta?.gapResourceCount ?? 0);

    if (isGapNode) {
      return children.length === 1
        ? 'live-status-detailed'
        : 'live-status-global';
    }

    if (isResourceNode && gapResourceCount > 1) {
      return 'live-status-global';
    }

    return 'live-status-detailed';
  }

  private normalizeDefaultRouteName(routeName: string): string {
    if (routeName === 'epart-board-dashboard') {
      return 'epart-board-resource';
    }

    if (
      routeName === 'live-status-dashboard' ||
      routeName === 'live-status' ||
      routeName === 'live-status-resource'
    ) {
      return 'live-status-detailed';
    }

    return routeName;
  }

  private resolveRouteParameter(
    node: TreeNodeType,
    targetRouteName: string,
    isLiveStatusRoute: boolean,
  ): { name: string; value: string } | undefined {
    const defaultParameterName = this.getDefaultParameterName(targetRouteName);

    if (isLiveStatusRoute && targetRouteName === 'live-status-detailed') {
      const detailedValue = this.resolveDetailedResourceValue(node);
      return detailedValue
        ? { name: 'resourceId', value: detailedValue }
        : undefined;
    }

    if (defaultParameterName === 'gapId') {
      if (!node.meta?.gapId) {
        return undefined;
      }

      return { name: 'gapId', value: String(node.meta.gapId) };
    }

    const value = String(node.value || '');
    return value ? { name: defaultParameterName, value } : undefined;
  }

  private getDefaultParameterName(targetRouteName: string): string {
    const targetRoute = this.router
      .getRoutes()
      .find((routeRecord) => routeRecord.name === targetRouteName);

    return (targetRoute?.meta?.paramName as string) || 'resourceId';
  }

  private resolveDetailedResourceValue(node: TreeNodeType): string | undefined {
    if (node.meta?.resourceId) {
      return String(node.meta.resourceId);
    }

    const children = Array.isArray(node.children) ? node.children : [];
    const onlyChild = children.length === 1 ? children[0] : undefined;

    if (onlyChild?.meta?.resourceId) {
      return String(onlyChild.meta.resourceId);
    }

    if (onlyChild?.value) {
      return String(onlyChild.value);
    }

    return undefined;
  }

  private pushRoute(
    targetRouteName: string,
    parameterName: string,
    parameterValue: string,
  ): void {
    const newParameters: Record<string, string> = {
      [parameterName]: parameterValue,
    };

    if (this.route.params.language) {
      newParameters.language = String(this.route.params.language);
    }

    this.router.push({
      name: targetRouteName,
      params: newParameters,
    });
  }
}

