 * @param productionLine - The production line to check
 * @param parameterValue - The parameter value to search for
 * @param parameterName - The parameter name to search for
 * @returns True if the resource exists
 */
function checkProductionLineWorkcenters(
  productionLine: ApiProductionLine,
  parameterValue: string,
  parameterName: string,
): boolean {
  return (
    productionLine.workcenters?.some((wc) =>
      checkWorkcenterResources(wc, parameterValue, parameterName),
    ) ?? false
  );
}

/**
