 * @param plant - The plant to check
 * @param parameterValue The parameter value to search for
 * @param parameterName The parameter name to search for
 * @returns True if the resource exists
 */
function checkPlantUaps(
  plant: ApiPlant,
  parameterValue: string,
  parameterName: string,
): boolean {
  return (
    plant.uaps?.some((uap) =>
      checkUapProductionLines(uap, parameterValue, parameterName),
    ) ?? false
  );
}

/**
 * Searches for a parameter value in the API structure
 * @param apiPlants - The plants array to search
 * @param parameterValue The parameter value to search for
 * @param parameterName The parameter name to search for
 * @returns True if the parameter value exists
 */
function searchApiStructure(
  apiPlants: Array<unknown>,
  parameterValue: string,
  parameterName: string,
): boolean {
  return apiPlants.some(
    (plant) =>
      typeof plant === 'object' &&
      plant !== null &&
      'uaps' in plant &&
      checkPlantUaps(plant as ApiPlant, parameterValue, parameterName),
  );
}

/**
 * Searches for a resource ID in the transformed tree structure
 * @param treeNodes - The tree nodes to search
 * @param resourceId - The resource ID to search for
 * @returns True if the resource exists
 */
function searchTreeStructure(
  treeNodes: Array<TreeNodeType>,
  resourceId: string,
): boolean {
  return treeNodes.some(
    (node) =>
      (!node.children && node.value === resourceId) ||
      (Array.isArray(node.children) &&
        node.children.length > 0 &&
        searchTreeStructure(node.children, resourceId)),
  );
}
/**
 * Searches for a gapId in the transformed tree structure
 * @param treeNodes - The tree nodes to search
 * @param gapId - The gapId to search for
 * @returns True if the gapId exists
 */
function searchTreeGapId(
  treeNodes: Array<TreeNodeType>,
  gapId: string,
): boolean {
  return treeNodes.some((node) => {
    // Check current node first (regardless of children)
    if (node.meta?.gapId && String(node.meta.gapId) === gapId) {
      return true;
    }
    // Then check children
    if (Array.isArray(node.children) && node.children.length > 0) {
      return searchTreeGapId(node.children, gapId);
    }
    return false;
  });
}

/**
 * Checks if a specific parameter value exists within the given data structure
 * @param data - The data structure to search (either API or tree structure)
 * @param parameterValue The parameter value to check for existence
 * @param parameterName The parameter name ('resourceId' or 'gapId')
 * @returns True if the parameter value exists, otherwise false
 */
export function checkResourceIdExists(
  data: Array<unknown>,
  parameterValue: string,
  parameterName = 'resourceId',
): boolean {
  if (data.length === 0) return false;

  const firstItem = data[0];
  if (typeof firstItem !== 'object' || firstItem === null) return false;

  // Check if it's API structure (has uaps property)
  if ('uaps' in firstItem) {
    return searchApiStructure(data, parameterValue, parameterName);
  }

  // Check if it's tree structure (TreeNodeType with id, label, value properties)
  if ('value' in firstItem && 'label' in firstItem) {
    if (parameterName === 'gapId') {
      // For tree structure with gapId, we need to search for nodes with matching gapId meta
      return searchTreeGapId(data as Array<TreeNodeType>, parameterValue);
    }
    return searchTreeStructure(data as Array<TreeNodeType>, parameterValue);
  }

  return false;
}

/**
 * Navigates to a specific path with an optional resource ID and configurable suffix.
 * @param router - The router instance used for navigation.
 * @param router.push - Function to perform navigation.
 * @param path - The base path to navigate to.
 * @param [resourceId] - Optional resource ID to include in the path.
 * @param [fallbackPath] - Optional fallback path if resourceId is not provided.
 * @param [pathSuffix] - Optional suffix to append if resourceId exists .
 */
export function goToPageWithResourceId(
  router: { push: (path: string) => void },
  path: string,
  resourceId?: string,
  fallbackPath?: string,
  pathSuffix = '',
): void {
  const targetPath = resourceId
    ? `${path}/${resourceId}${pathSuffix}`
    : (fallbackPath ?? path);

  router.push(targetPath);
}

/**
 * Checks if the specified action is allowed for the current user.
 * @param actionName - The name of the action to check.
 * @returns True if the action is allowed; otherwise, false.
 */
interface UserAction {
  object?: string;
  actionType?: string;
}

/**
 * Checks if the specified action is allowed for the current user.
 * @param actionName - The name of the action to check.
 * @returns True if the action is allowed; otherwise, false.
 */
export function isActionAllowed(actionName: string): boolean {
  const userAuth = useProfileStore();
  const actions: Array<UserAction> = (userAuth.$state as any).userActions || [];
  return actions.some(
    (action: UserAction) =>
      action.object?.toLowerCase() === actionName.toLowerCase() &&
      action.actionType?.toLowerCase() === 'enable',
  );
}

